// ═══════════════════════════════════════════════════════════
// WAT IS ER NIEUW: ÉÉN REGEL PER WIJZIGING, NOOIT EEN REGEL HERSCHRIJVEN
// ═══════════════════════════════════════════════════════════
// Hier stond ooit één zin, `LAATST_BIJGEWERKT`, waar elke chat zijn nieuws
// vóórin plakte. Die zin groeide naar vijfduizend tekens op één regel, en
// iedere chat die iets opleverde herschreef precies díe regel. Twee chats op
// dezelfde dag botsten dus gegarandeerd, en op 11 augustus 2026 zijn de
// conflictmarkeringen twee keer meegecommit. Gevolg: de bouw mislukte, de site
// bleef twee opleveringen lang op oude code staan, en niemand zag het.
//
// Daarom nu twee afspraken die samen het botsen onmogelijk maken:
//
//  1. ÉÉN WIJZIGING IS ÉÉN REGEL, EN JE VOEGT HEM BOVENAAN TOE. Je past nooit
//     een bestaande regel aan. Twee chats die allebei iets toevoegen maken dan
//     twee losse regels, geen twee versies van dezelfde regel.
//  2. `.gitattributes` ZET DIT BESTAND OP `merge=union`. Botsen twee chats
//     toch op dezelfde plek, dan houdt git ze allebei in plaats van er een
//     conflict van te maken. Er kunnen hier dus nooit conflictmarkeringen in
//     belanden, en dat is precies wat de bouw sloopte.
//
// Voorwaarde voor punt 2: elke regel moet op zichzelf kloppen. Vandaar de
// vaste, eenregelige vorm hieronder. Verdeel een lange tekst nooit over
// meerdere regels; dan kan een union-merge er wél iets kapots van maken.
// `proeven/wat-is-nieuw.proef.ts` bewaakt die vorm bij elke bouw.
// ═══════════════════════════════════════════════════════════

export type Nieuwtje = { datum: string; tekst: string };

/** Nieuwste bovenaan. Datum als JJJJ-MM-DD, tekst in gewone taal, één regel. */
export const WAT_IS_NIEUW: Nieuwtje[] = [
  { datum: "2026-08-21", tekst: "Een opvolgdatum die in de database stond, maar op het scherm leeg bleef, is er weer. Een datumkolom komt niet als tekst terug en werd verkeerd afgesneden, waardoor het vakje leeg leek en de datum bij het eerstvolgende opslaan echt gewist werd. Het viel op bij twee extra regels onder een lead. Dat gebeurt nu overal op één manier." },
  { datum: "2026-08-21", tekst: "De leadlijst en de klantenlijst werken als een werkblad. Elk vakje bewaart zichzelf zodra je stopt met typen, dus je hoeft er niet meer uit te klikken. De omgeving erachter open je alleen nog door op de bedrijfsnaam te klikken, niet meer door ergens in de rij te klikken. Er is een kolom Kosten eenmalig bij gekomen, rechts van Eenmalig, zodat je naast wat een website oplevert ook ziet wat hij jou kost. Verwacht klant staat kort in beeld (sept '27, of N.B. als je hem nog niet weet) in plaats van de volle maandnaam, en de opvolgdatum die geweest is krijgt een zacht oranje vlakje in plaats van een harde rode regel. De knoppen en het rode kruisje staan rechts uitgelijnd, dus een extra regel schuift niet meer scheef. En een extra regel neemt de opvolgdatum over van het bedrijf erboven en loopt daarmee mee, ook als HubSpot hem verzet." },
  { datum: "2026-08-20", tekst: "Op een taakregel in de planning is meer ruimte voor de titel. De standkeuze heet nu dev in plaats van bij developer en is smaller, en de datumknop heet datum in plaats van dag kiezen en is ook smaller. Die twee woorden aten samen ruim zestig pixels op, precies waar een lang pad als /lensimplantatie/refractive-pro-art-lens/ moet staan. Wat een stand betekent lees je door erover te gaan staan." },
  { datum: "2026-08-20", tekst: "Mail vanuit een kaart en doorzetten naar de sitebouwer tonen nog maar één versie per soort: de laatste analyse, blauwdruk en copy. De eerdere rondes staan achter een knopje Oudere versies." },
  { datum: "2026-08-20", tekst: "Het vraagveld bij Laatste mails zoekt nu ook echt in je mailbox op de woorden uit je vraag. Het las alleen de zestig recentste mails van die klant en deed met je vraag verder niets, dus een mail van drie weken terug bestond voor het antwoord simpelweg niet: je vroeg naar een mailwisseling die in Superhuman gewoon zichtbaar was en kreeg te horen dat er maar één was. En een verschreven naam wordt eerst bijgetrokken tegen de mensen met wie je bij die klant echt mailt, dus \"pehlevian\" wordt \"Pehlivan\". Is er op een andere schrijfwijze gezocht dan je typte, dan staat dat in het antwoord." },
  { datum: "2026-08-20", tekst: "Het Developer-tabblad opent op de weekplanning in plaats van op de lijst per klant. Dat scherm gaat over wanneer er wat gebeurt, en dat is de vraag die je stelt als je hem opent; de lijst per klant is naslag en staat er één klik naast. En hij landt nu net iets lager: de regel \"Week van …\" met het chipje DEZE WEEK viel precies achter de vaste kopbalk, zodat je van donderdag alleen de onderste helft zag." },
  { datum: "2026-08-20", tekst: "De voorvertoning die verschijnt als je een documentlink aanwijst is groter geworden: van 384 bij 300 naar 600 bij 460. Bij een spreadsheet zag je eerst twee kolommen en drie regels, net genoeg om te zien dát het een tabel was. Op een smal of laag scherm krimpt hij mee, en hij wordt binnen het venster gehouden, ook als je een link onderaan de pagina aanwijst." },
  { datum: "2026-08-20", tekst: "Pas je de titel van een taakkaart aan nadat hij naar de developer is doorgezet, dan ziet hij die nieuwe titel ook. De aantekeningen liepen al mee (die worden live gelezen), de titel bleef hangen op de formulering van het moment van doorzetten. Je eigen formulering blijft wél gewoon staan zolang de kaart niet verandert: daar is over nagedacht en die mag niet zomaar overschreven worden. Het dashboard onthoudt daarvoor bij het doorzetten hoe de kaart toen heette; wijkt de kaart daar later van af, dan is die eigen tekst ingehaald en wint de kaart weer." },
  { datum: "2026-08-20", tekst: "De knoppen Nieuwe lead en Nieuwe klant zetten het formulier nu bovenaan het blok neer in plaats van onder de hele lijst; met zestien regels eronder zag je hem niet en leek er niets te gebeuren. Op de leadkaart heten de velden voortaan SEO p/m, Ads p/m, Linkbuilding p/m en Kosten p/m, en staan de invulvakjes op één lijn ook als een label omslaat." },
  { datum: "2026-08-20", tekst: "Je kunt de leadlijst nu sorteren: klik op Opvolgen, Kans, Budget, Kosten, Eenmalig of Verwacht klant. Eén keer klikken is laag naar hoog, nog een keer hoog naar laag, en de derde keer staat je eigen sleepvolgorde er weer. Lege vakjes staan altijd onderaan. De maand kies je nu uit een lijst die twee jaar vooruit loopt, dus volgend jaar erbij zoeken hoeft niet meer. Achter de naam van een lead die uit HubSpot komt staat (HS) met de directe link naar dat contact. En de knop + regel werkt weer: er ontbrak een kolom in de database waardoor hij stilletjes niets deed." },
  { datum: "2026-08-20", tekst: "Staat een bedrijf twee keer in je leadlijst (één keer zoals jij het had staan, één keer zoals het uit HubSpot kwam), dan meldt het dashboard dat en zet het de paren op een rij: Spijker en Prins naast Hoveniersbedrijf Spijker & Prins, Tudor Kozijnen naast TUDOR. Met één knop voeg je ze samen. De rij met jouw bedragen blijft staan en wint op alles wat daar ingevuld is; wat daar leeg is wordt aangevuld uit de andere, en het dossier, de documenten, de mail en de HubSpot-koppeling verhuizen mee. Er gaat dus niets verloren, en samenvoegen gebeurt nooit vanzelf." },
  { datum: "2026-08-20", tekst: "Je HOT-leads komen nu echt binnen uit HubSpot. De ronde meldde maandenlang \"nog niet ingesteld\" terwijl je filter gewoon gevuld was: het uitlezen van de instellingen gaf in een verse serverronde leeg terug, precies dezelfde vraag een regel later wel. Alle instellingen worden nu in één keer gelezen, langs één weg. Op het beheerscherm staat er voortaan bij wát een ronde vond en waarop hij gezocht heeft, zodat \"hij vindt niemand\" nooit meer op \"hij draait niet\" lijkt." },
  { datum: "2026-08-20", tekst: "Een extra regel is nu een echte kopie van de rij erboven: hetzelfde bedrijf met dezelfde link naar hun site, en precies dezelfde kolommen, maar leeg. Je vult zelf in waar hij over gaat en wat hij oplevert, dus de ene regel wordt de SEO en de andere de website, met een eigen opvolgdatum, een eigen kans, een eigen bedrag en een eigen startmaand. De kolom Soort is op elke regel een keuzelijst geworden, ook op de rij van het bedrijf zelf; die keuze stuurt de uitsplitsing onder de maandstrook. Er worden bewust geen bedragen meegekopieerd: dan zou alles dubbel meetellen tot je het had rechtgezet." },
  { datum: "2026-08-20", tekst: "De knop \"+ regel\" dupliceert nu de rij waar je op staat: hetzelfde maandbedrag, dezelfde kosten, hetzelfde eenmalige bedrag en dezelfde startmaand. Daarna maak je van de ene regel de website en van de andere de SEO, of Google Ads. In beide lijsten staat er links een kolom Soort: bij een extra regel kies je daar SEO, advertenties, website of overig, en die keuze stuurt de uitsplitsing onder de maandstrook. Een extra regel heeft ook een eigen Verwacht klant, zodat een website in een andere maand kan vallen dan de SEO." },
  { datum: "2026-08-20", tekst: "Eén bedrijf kan nu meer dan één regel hebben: met de knop \"+ regel\" zet je de website, de SEO en Google Ads onder elkaar, elk met een eigen bedrag, eigen kosten en een eigen soort. Die regels rekenen mee in de prognose en in de maandstrook, met dezelfde kans als het bedrijf waar ze onder hangen. In die strook kun je de regels bestaande klanten en leads nu openklappen: dan zie je per bedrijf wat het per maand bijdraagt en met welke kans er gerekend is. En de HubSpot-ronde haalt voortaan alles op zodra je het filter verandert of nog niets binnen hebt; hij vroeg alleen naar wat er sinds het laatste kwartier gewijzigd was, en daardoor bleef je opvolgdatum leeg terwijl het filter goed stond." },
  { datum: "2026-08-20", tekst: "Je klantenlijst werkt nu net als je leadlijst: maandfee en kosten vul je direct in de rij in, en ernaast staat wat je er netto aan overhoudt, met onderaan de optelling van alle drie. E-mail en uurtarief zijn uit die lijst weg, net als het uitklapvak voor het budget en de knoppen Budget en Nieuw wachtwoord (een nieuw klantwachtwoord maak je op Beheer); verwijderen is een rood kruisje geworden. Bij de leads is er een kolom Kosten p/m bijgekomen, en de opvolgdatum kun je daar nu zelf invullen zolang HubSpot er geen levert." },
  { datum: "2026-08-20", tekst: "Onder je leads staat nu een strook met de komende zes maanden naast elkaar: wat je bestaande klanten opleveren, wat je leads daar gewogen bovenop doen, en wat dat samen per maand wordt, met eronder de uitsplitsing naar SEO, advertenties en eenmalig. Het zijn dezelfde cijfers als in de volledige prognose, dus twee schermen kunnen nooit een ander getal geven. In de lijst zelf is de kolom Website weg (de bedrijfsnaam is nu de link naar hun site), staan de totalen netjes onder de bedragen uitgelijnd, en is de knop Niet doorgegaan een rood kruisje geworden." },
  { datum: "2026-08-20", tekst: "De leadlijst is een werkblad geworden: per rij vul je nu ook de kans in procenten en een eenmalig bedrag in, naast het maandbedrag en de startmaand. Onder de lijst staat wat het bij elkaar is, in twee getallen: opgeteld en gewogen, dus elk bedrag maal de kans van die lead. De kolom die op elke rij \"zelf gemaakt\" liet zien is eruit, de bedragkolommen zijn smal, en van de twee knoppen die hetzelfde deden is alleen \"Niet doorgegaan\" overgebleven; echt verwijderen kan nu onderaan de leadkaart, een klik dieper, want dat is onomkeerbaar." },
  { datum: "2026-08-20", tekst: "Op je startscherm staan de leads en je eigen klanten meteen open in plaats van dichtgeklapt, en in de leadlijst vul je het maandbedrag en de maand waarin iemand naar verwachting start nu direct in de rij in. Je hoeft die lead dus niet meer te openen om te noteren wat je verwacht; wat je typt is hetzelfde bedrag als op de leadkaart en telt meteen mee in de prognose. Vulde je alleen een startmaand in, dan ging die lead voorheen stilletjes voor honderd procent meetellen; nu blijft hij op de dertig procent van een lead die je nog niet beoordeeld hebt." },
  { datum: "2026-08-20", tekst: "De leads die uit HubSpot binnenkomen kun je nu ook op eigenaar filteren, dus niet alleen op leadstatus. Zet je de status op HOTHOTHOT en de eigenaar op jezelf, dan komt precies hetzelfde lijstje binnen als je opgeslagen weergave in HubSpot, en niets anders. Boven het beheerscherm staat in één zin wat er binnenkomt, zodat je vóór het ophalen ziet wat je krijgt. Wat er per ongeluk eerder binnenkwam ruim je op met de knop erboven; contacten die niet meer aan het filter voldoen worden daar vanzelf bij aangeboden." },
  { datum: "2026-08-20", tekst: "Elke fase op een projectkaart laat nu zien wanneer hij voor het laatst iets opleverde, en dat is de échte datum: het moment waarop het document gemaakt werd, de strategie is vastgelegd of het advies is doorgegeven. Er stond al een teller in die rij, maar die begon pas te tellen vanaf het moment dat hij gebouwd werd, dus een fase die al maanden af was zou vandaag gaan heten. Precies het verkeerde antwoord op de vraag waar het om gaat: kijk ik naar oud of naar nieuw werk? Bij een pagina met vijf groene vinkjes zie je nu in één blik dat de strategie van vandaag is en de documenten van drie weken terug." },
  { datum: "2026-08-20", tekst: "Plak je een Google-document, spreadsheet of presentatie in een tekstveld, dan komt de naam van dat bestand in beeld in plaats van een adres van honderd tekens. De link blijft dezelfde en het volledige adres staat als tooltip erbij. Heb je er zelf een woord van gemaakt, dan blijft dat staan; dat is een bewuste keuze. Het opzoeken gebeurt ná het plakken, dus je tekst staat er meteen en de naam volgt een tel later; lukt het niet, dan blijft de link gewoon staan." },
  { datum: "2026-08-20", tekst: "Een taakkaartje in de developerplanning toont weer alleen waar het om gaat: de klant, de volledige titel en de knoppen Klaar, Afgerond, Bekijk en Mail. Het knopje naar de opmerkingen en de documentlinks zijn eraf; die staan achter Bekijk, samen met de aantekeningen van de kaart. Een kaartje in een weekplanning is een kaartje, geen dossier." },
  { datum: "2026-08-20", tekst: "Op een projectkaart zie je nu per fase wanneer hij is vastgelegd: achter Strategie, Analyse, Blauwdruk, Copy en de rest staat de datum en de tijd, met bij aanwijzen de volledige zin erbij. Dat is de bevestiging dat de volgende stap met de verse versie werkt en niet met een oude, en het laat meteen zien waar je gebleven was. Een fase die nog niet af is en langer dan een dag stilstaat, laat in plaats daarvan zien hoe lang hij al wacht." },
  { datum: "2026-08-20", tekst: "Een strategie-document dat op de achtergrond mislukt, meldt dat nu zelf. Die stap draait nadat de kaart al \"het document wordt gemaakt\" heeft gezegd, dus liep hij stuk, dan zag je niets: er kwam alleen nooit een document. Nu komt het als interne werkzaamheid in de tijdlijn van die pagina te staan, met de reden erbij en de mededeling dat de vastgelegde strategie zelf er gewoon staat. En als een pagina meerdere strategie-documenten heeft (een oude en een nieuwe), wijst de link altijd naar de nieuwste; hij wees soms naar de versie van vóór de herziening terwijl de fase ernaast over de nieuwe ging." },
  { datum: "2026-08-20", tekst: "De verloren deals en oud-klanten zijn helemaal uit beeld: niet meer in het beheerscherm, niet in de klantenkiezer in de kopbalk, niet in het fundament-overzicht. Ze stonden even in een dichtgeklapt blok, maar een blok dat je nooit opent is geen naslag. Ze blijven in de database staan; opruimen doe je met de knop op Beheer. En de kraan staat dicht: een HubSpot-ronde op deals zonder gekozen pijplijn haalt niets meer op en zegt dat ook, want die combinatie leverde 127 leads op. Bij Pingwin is een lead een contact met een leadstatus; ook die weg doet niets zolang je niet hebt gekozen welke leadstatus telt. Verder heeft de fase Strategie nu ook een link naar zijn document als die taak uit een oudere ronde komt, en op de developerplanning is de titel van een taak volledig te lezen (ook over twee regels), zonder pil \"naar dev\" en zonder de linkjes uit de aantekeningen; die staan achter Bekijk." },
  { datum: "2026-08-20", tekst: "Wat er vanaf een taakkaart meegaat naar de developer gaat alleen nog over stukken die hij kan openen: het stappenplan, de bespreekpunten, een locatie. Mailadressen en telefoonnummers komen er niet als losse link bij. Dat gebeurde één ronde wel, en dan kreeg het mailvenster zeven vinkjes waarvan er vijf een vestigingsadres waren, met onderaan de mail een rijtje adressen. Die adressen zijn niet kwijt: ze staan in de aantekeningen die in hun geheel meereizen, bij de vestiging waar ze bij horen. De stukken heten nu ook gewoon naar wat ze zijn, zonder het voorvoegsel Uit de kaart." },
  { datum: "2026-08-20", tekst: "Wat je bij een taak in de aantekeningen zet, gaat nu mee naar de developer. Dat veld is het enige op een kaart dat geen automatische stap aanraakt, dus wat er staat heb je er bewust neergezet, en juist dat bleef achter: de developer kreeg de titel, de pagina en de documenten uit de pijplijn, en verder niets. Nu staan de aantekeningen volledig in het taakvenster op de developerpagina, opgemaakt zoals op de kaart, met werkende links en uitklappers. Elke link uit de kaart en de aantekeningen staat daar ook nog los op een rij, en op het compacte kaartje in de lijst naast de documenten. In het doorzet-venster kun je ze aan- of uitvinken; ze staan standaard aan. De mail neemt ze mee als klikbare regels, met de aantekeningen als gewone tekst eronder, en de assistent die de mail schrijft kent ze nu ook, dus hij schrijft niet langer om adressen en namen heen die er gewoon staan. Ook kale adressen en mailadressen in de tekst tellen mee." },
  { datum: "2026-08-20", tekst: "Elk gesprek laat nu zien van wanneer het is: in de gesprekkenlijst op de takenpagina, bij de eerdere chats van een pagina, op de projectkaart, in de gesprekkenkeuze van het zwevende venster en bij de chatregels in het dossier van een pagina. Wijs de datum aan en je ziet de volledige datum plus hoe lang geleden dat was, en of het gesprek over meerdere dagen liep. Ook de vastgelegde strategie zegt nu wanneer hij is vastgelegd, zodat een tabblad dat nog openstaat niet stiekem de vorige versie toont. Reden: op een pagina stond een gesprek uit juli naast een gesprek van vorige week met een herziene strategie, en die twee waren op het scherm niet uit elkaar te houden, terwijl alle fases erna op de laatste conclusie draaien." },
  { datum: "2026-08-20", tekst: "De klantenlijst gaat weer over klanten. Sinds de HubSpot-koppeling komen deals vanzelf binnen, en een deal die niet doorgaat kreeg de stand \"niet doorgegaan\"; die viel uit de leadlijst en kwam ómhoog te staan, tussen de echte klanten. Daardoor stonden er honderdvierentwintig rijen onder \"Mijn eigen klanten\", vol hosting- en websitedeals. Niet doorgegaan en oud-klanten hebben nu hun eigen blok dat standaard dicht staat, in het beheerscherm én in de klantenkiezer in de kopbalk; ze blijven gewoon bewaard met hun mails en dealwaarde. De bulk-onboarding, de klantwaarde-lijst en het fundament-overzicht rekenden ze ook mee en doen dat niet meer." },
  { datum: "2026-08-20", tekst: "Bij de fase Strategie staat nu net als bij analyse, blauwdruk en copy een link naar het document. Dat document werd al gemaakt, maar was op de kaart nergens te vinden. Daarnaast: het samenvatten van een gesprek tot een vastgelegde strategie liep soms stuk met alleen de melding \"probeer het nog een keer\". De oorzaak was een tweede AI-stap die na het samenvatten begon zonder eigen klok, waardoor het geheel over de tijdslimiet van vijf minuten kon lopen. Alles telt nu mee in één begroting, het samenvatten krijgt vooraf ruimte voor een lang antwoord in plaats van het driemaal opnieuw te proberen, en gaat er tóch iets mis, dan staat de echte reden in beeld." },
  { datum: "2026-08-20", tekst: "Het Pagina-lab geeft nu zelf een oordeel over één pagina, met de criteria, de meting en de foto naast elkaar. Op /admin/pagina-lab kies je een klant en plak je een adres; het lab bezoekt de pagina twee keer (desktop en telefoon), leest hem, meet hem en fotografeert hem, en houdt hem daarna tegen de tweeëndertig criteria uit de kennisbank. Per criterium komt er één bevinding terug: wat er op deze pagina te zien is, wat we zouden doen, waarom het uitmaakt, en waar het oordeel op rust. De foto blijft links in beeld terwijl je door de bevindingen leest, en onder elke bevinding staat de meting waar hij op steunt. Nieuw is ook wat er gemeten wordt: contrast van elke tekstsoort tegen zijn echte achtergrond, tekstgrootte en regellengte, formuliervelden met en zonder zichtbaar label, of je kunt inzoomen, of de inhoud op een telefoonscherm past, knoppen die te klein zijn om te raken, wat er bij binnenkomst over de pagina heen ligt, laadtijd en verspringen. Drie grenzen zitten in de code en niet in een afspraak: een bevinding zonder geldige criteriumcode wordt weggegooid, een criterium dat uit een meting hoort te komen zonder meting wordt \"niet vast te stellen\" in plaats van een indruk, en het waarom plus de bron komen letterlijk uit de kennisbank, nooit uit het model. Wat er is afgevallen staat onderaan in beeld, en de criteria die niet beoordeeld zijn worden met naam genoemd. Er wordt nog niets bewaard: het lab leest mee en schrijft nergens iets weg." },
  { datum: "2026-08-19", tekst: "De HubSpot-koppeling kijkt nu naar je contacten in plaats van naar deals, want zo werk je: iedereen met de leadstatus die je op Beheer aanwijst (bijvoorbeeld hot) komt automatisch als lead in het dashboard, met naam en bedrijf, mailadres en telefoon, de website en de opvolgdatum. Die opvolgdatum komt uit een eigen veld als je dat hebt, en anders uit je eerstvolgende openstaande taak bij dat contact. De bedragen komen bewust niet uit HubSpot: bij een lead vul je zelf het SEO-bedrag per maand in, advertenties per maand, de kosten die erbij horen, en een eenmalig bedrag voor een website met de kosten daarvan, plus de kans en de maand waarin hij naar verwachting start. De prognose rekent daar meteen mee: maandbedragen tellen vanaf de startmaand elke maand mee, het eenmalige bedrag precies één keer. Wat je zelf zet wordt nooit door een ronde overschreven." },
  { datum: "2026-08-19", tekst: "De vraag \"welke versie geldt?\" bij de documenten van een taak wordt alleen nog gesteld waar hij bestaat. Twee documenten van hetzelfde soort golden als twee versies van elkaar, ook als het twee losse projecten waren; je kreeg dan een keuze voorgelegd die niet bestond, en het stuk dat je niet aanvinkte leek daarmee vervallen. Nu telt het onderwerp mee (uit de naam van het document): een teruggestuurde klantversie hoort bij zijn origineel en vraagt om een keuze, twee losse stukken gelden allebei gewoon. Een proef bewaakt allebei de kanten, want ze zijn even fout als ze omslaan." },
  { datum: "2026-08-19", tekst: "Bij elk document in een taak staat een knop \"Ondersteunend maken\". Levert een klant een blog of projectverhaal aan dat over hetzelfde onderwerp gaat als een landingspagina, dan pakt dat stuk anders de plek van die pagina in Google af. Je kiest nu één of twee landingspagina's, eventueel de zoekwoorden en de Drive-map, en het dashboard maakt er een ondersteunend stuk van: de landingspagina houdt zijn commerciële zoekwoord, het stuk pakt de vragen eromheen en geeft zijn kracht door met een interne link waarvan de linktekst juist wél die term bevat. De tekst zelf blijft van de klant; alleen de titel, de botsende koppen, de meta en de links schuiven, en elke aanpassing staat op een rijtje. Er wordt niets overschreven: het aangeleverde stuk blijft staan en er komt een nieuw document naast. Drie dingen worden nagerekend in plaats van beloofd (hoofdterm niet in de titel, er loopt echt een link, en de hoofdterm staat in de linktekst); klopt er iets niet, dan zie je dat als waarschuwing." },
  { datum: "2026-08-19", tekst: "De SEO-assistent (het zwevende venster) en de chat in het Overview-blok zijn één tool geworden. Het waren twee schermen op dezelfde motor, maar met verschillende kennis: het Overview-blok kende de hele site (paginalijst, werkstatus per pagina, zoekwoordstand, de koers, de concurrenten), het zwevende venster kende de klant (mail, stand van zaken, lopende werkzaamheden, Search Console-totalen en -trend, Google Ads). Welke je kreeg hing af van welk venster je opende, en dat was nergens te zien. Nu krijgt elk gesprek alles, staan in allebei de vensters dezelfde gesprekken, en kun je in het ene verdergaan waar je in het andere gebleven was. De keuzelijst van het zwevende venster toonde ook nog eens elk gesprek uit de database met zijn technische naam (`overzicht:~mshj4bjy`), inclusief die van de bird's eye; die krijgen nu een leesbare titel. De Ads-assistent, de leadomgeving en de pagina-chat blijven bewust apart." },
  { datum: "2026-08-19", tekst: "Het Pagina-lab weet nu ook wat bezoekers op een pagina dóen, niet alleen hoe hij eruitziet. Op /admin/pagina-lab staat onder Gedrag per klant of Analytics en Clarity bekend zijn, en kun je één pagina uitproberen: weergaven, hoeveel sessies daar begonnen, hoeveel mensen betrokken raakten of meteen weg waren, de tijd op de pagina en de conversies, apart voor mobiel en desktop. Die verdeling verandert vaak het hele oordeel. Analytics zoekt de property zelf op bij het domein; klopt dat niet, dan leg je het nummer met de hand vast. Clarity is helemaal nieuw en meet wrijving (dode klikken, woedeklikken, terugspringen, scrolldiepte); die koppeling is gebouwd en wacht op een account. Clarity staat maar tien opvragingen per dag toe en gaat nooit verder terug dan drie dagen, dus elke opvraging wordt bewaard en alles leest daarna uit dat archief. Een proef bewaakt dat de sleutel nooit naar de browser gaat en dat er niet per pagina opgehaald wordt." },
  { datum: "2026-08-19", tekst: "Het blok 'Site-wide strategie' is van de takenpagina af. Dat blok vulde zichzelf met een analyse en actiepunten uit een chatgesprek, op een plek waar je dat niet verwacht en niet zelf bijhoudt, terwijl de grote lijn al in 'De koers' staat. De SEO-assistent krijgt in ruil dezelfde knop als de bird's eye-chat: 'Wat volgt hieruit?' leest het hele gesprek terug en geeft een voorstel met vinkjes; wat je aanvinkt wordt meteen een taak in de weekplanning. Er is dus nog één weg van gesprek naar werk in plaats van twee. De vastgelegde gesprekken blijven in de database staan, er is niets weggegooid; de onboardingstap 'Strategie vastgelegd' heet nu 'De koers vastgelegd' en kijkt naar dat veld." },
  { datum: "2026-08-19", tekst: "In de documentenlijst van een taak staat de naam van een document nu helemaal in beeld in plaats van afgekapt met puntjes, en het tijdstip komt erbij zodra twee documenten van hetzelfde soort dezelfde dag dragen. Liggen er twee stukken copy voor twee verschillende onderwerpen in één taak, dan was juist het staartje van de titel het enige waaraan je ze uit elkaar hield, en dat viel weg." },
  { datum: "2026-08-19", tekst: "Aantekeningen bij een taak blijven nu ook echt staan. Ze werden al weggeschreven, maar de takenlijst eromheen hield de tekst vast zoals die bij het laden van de pagina was: klapte je de taak dicht en weer open, dan stond je aantekening er weer af, en typte je daarop verder dan ging de goede tekst er alsnog aan. In het weekbord over alle klanten werd de aantekening zelfs helemaal niet meegeleverd, dus was het veld daar altijd leeg. Wat je bewaart komt nu meteen in de lijst te staan, en een nieuwe proef bewaakt dat een kaart geen veld kan uitlezen dat de vraag aan de database niet ophaalt (dat gaf geen foutmelding, alleen een lege waarde)." },
  { datum: "2026-08-19", tekst: "Nog vijf rondes op de knoppen: van 38 naar 27 bestanden met een eigen knopnaam. Er zijn drie gedeelde vormen bij gekomen voor dingen die overal opnieuw verzonnen werden. De schakelaar (kiezen tussen twee weergaven, zoals Prognose of Boekhouding, Lijst per klant of Weekplanning) had vijf verschillende vormen, waarvan drie zonder eigen naam: die leunden op een klasse van het blok eromheen. De werkbalk van een tekstveld (vet, cursief, opsomming, link) had twaalf knoppen die geen enkele controle kon zien omdat ze helemaal geen naam hadden, en er waren twee vormen van diezelfde werkbalk. En zes eigen inklapkoppen (werklijst, kennisbank, planning, bedrijfsgegevens, dossierlijst, achtergrond op een actiekaart, plus de twee in het financieel overzicht die met losse opmaak in de code stonden) staan nu op de gedeelde kop." },
  { datum: "2026-08-19", tekst: "Zes verschillende vormen voor precies hetzelfde ding (een kop waar je op klikt om iets open te klappen) zijn er twee geworden. Niveau 1 is de kleurverloop-balk die je kent van het beheerscherm en de cockpit: die zit nu ook op het mailfilter, de KPI-secties, de cannibalisatie-analyse, het interne-links-voorstel en het structured-data-advies. Niveau 2 is een kop bínnen zo'n paneel: hetzelfde driehoekje, maar rustig met een lijntje, voor de KPI-subsecties, 'Gedaan' in het weekplan, 'Besproken maar bewust geen taak' en de JSON-LD. In het weekplan zei de kléur van de kop de stand (groen gedaan, blauw gepland, oranje bezig); die staat nu als labeltje ernaast, want een kop die per stand verkleurt is geen gedeelde kop. Drie bestanden gingen van de lijst met eigen knopnamen af, 41 naar 38." },
  { datum: "2026-08-19", tekst: "HubSpot is gekoppeld: je deals komen elk kwartier binnen als lead, met de fase, het bedrag, de datum waarop ze naar verwachting klant worden en het eerstvolgende contactmoment uit je openstaande taken daar. De notities en gespreksverslagen landen in het dossier van die lead, dus het gesprek weet wat er besproken is. Bovenaan een lead staat nu een kaart met die stand plus het beoogde maandbudget dat je zelf zet; in de leadlijst zie je per rij wanneer je moet opvolgen (rood als die dag geweest is), het budget en de verwachte startdatum. Daaronder staat de mailwisseling met dat bedrijf, met dezelfde mailknop als bij een klant, en een tijdlijn waarin mails, notities, documenten en metingen op datum onder elkaar staan. De prognose vult zich vanzelf met de kans uit de dealfase en de startmaand uit de sluitingsdatum; zet je die zelf, dan blijft jouw keuze staan. Andersom wijzigt het dashboard in HubSpot niets, behalve een notitie als je dat aanzet. Instellen op Beheer: welke pijplijnen als lead tellen, en de knop om nu op te halen." },
  { datum: "2026-08-19", tekst: "Het uitklap-driehoekje is overal hetzelfde geworden. Twaalf plekken in de opmaak hadden hun eigen driehoekje, elk met een eigen kleur en maat en allemaal met dezelfde bedoeling; twee ervan waren al grijs in plaats van oranje. Nu is het één vorm die bij openklappen een kwartslag draait, en het is geen letter meer maar een uitgeknipt vlakje, dus het staat op elk apparaat precies even hoog op de regel. In de schermen zelf gingen tachtig driehoekjes van een letter naar een tekening." },
  { datum: "2026-08-19", tekst: "De knoppencontrole las een kruisje dat als code geschreven is (&times;) niet als kruisje, en keurde daardoor zeven bestanden af die juist goed waren. Dat is hersteld; de lijst met bestanden die nog een eigen knopnaam gebruiken ging van 48 naar 41. Verder lezen achtenveertig plekken in de opmaak nu de naam van wat ze doen in plaats van de kale maat, dus de betekenislaag staat op 85,2%." },
  { datum: "2026-08-19", tekst: "Het beheerscherm stond vol zwarte balken en ziet er weer uit als de rest van het dashboard: zacht kleurverloop, oranje driehoekje, en per blok een icoontje in dezelfde tegel als de kop van een cockpit-kaart (vlaggetje bij Leads, mensen bij Klanten, gebouw bij Multimedia Concepts, lijstje bij de onboardingrij, muntje bij Klantwaarde, oog bij Meekijken). Oorzaak was één regel opmaak die de gedeelde inklapkaart een eigen zwarte achtergrond gaf. Nieuw is de controle die dat voortaan tegenhoudt: een gedeelde bouwsteen mag door een scherm wél anders neergezet worden (ruimte, uitlijning) maar niet anders gekleurd, omrand of belettert. Alle bestaande poorten stonden groen bij die zwarte balken, want die vroegen alleen of de regels gevolgd werden, nooit of het er hetzelfde uitzag." },
  { datum: "2026-08-19", tekst: "Lege vierkantjes in beeld zijn weg, en kunnen niet meer terugkomen. Montserrat heeft geen pijltjes, vinkjes, driehoekjes of sterretjes; welke tekens precies is nagemeten in de lettertypebestanden zelf in plaats van geraden. Die tekens worden nu bijgeladen als klein terugval-lettertype, uitgeknipt tot precies de tekens die we gebruiken, dus een paar honderd bytes. Ze zien er daardoor op elk apparaat hetzelfde uit, ook in tekst die het dashboard niet zelf schrijft: een antwoord van de AI, een geplakte strategie, de inhoud van een mail. De vierentwintig tekens die geen enkel lettertype kan tekenen (een kalender, een belletje, een slotje, drie stipjes, een delta) zijn vervangen door getekende icoontjes. Een controle vóór elke bouw wordt rood zodra er een teken in beeld komt dat niemand kan tekenen." },
  { datum: "2026-08-19", tekst: "Op het scherm Stijl stond 'Icoontjes als letter in beeld: 18 plekken → 0'. Dat getal was met de hand ingetypt en klopte niet: het waren er 419, waarvan er 24 als leeg vierkantje in beeld kwamen. Die regel wordt nu geteld in plaats van getypt, net als de zes meters eronder, en er staat bij hoeveel er onleesbaar zijn. Een getal dat niemand narekent is erger dan geen getal, want het zegt dat er niets meer te doen is." },
  { datum: "2026-08-19", tekst: "Het beheerscherm is één scherm geworden in plaats van één lange rol. Alle blokken (leads, klanten, Multimedia Concepts, de onboardingrij, klantwaarde en meekijken) staan standaard dicht, met een pijltje om ze open te klappen. De knop die bij een blok hoort staat rechts in de kopbalk van dat blok, dus '+ Nieuwe lead' bij de leads en '+ Nieuwe klant' bij de klanten; die stonden eerst los onderaan, achter alle rijen. Klik je erop terwijl het blok dicht staat, dan klapt hij vanzelf open met het formulier erin. En een klant die niet meer bestaat blijft niet langer als mislukte regel in de onboardingrij staan; die wordt nu opgeruimd." },
  { datum: "2026-08-19", tekst: "Veertien blokken maakten hun eigen alinea's, opsommingen en links bovenop de gedeelde opmaak, en op de pagina-kaart ging dat zichtbaar mis: het opsommingsteken in 'Waar deze pagina staat' waren twee halve tekens over elkaar, een rond bolletje met een chevron die eronderuit stak. Oorzaak: de browser kiest per eigenschap, dus de tekst van het teken kwam uit de gedeelde opmaak en het bolletje eromheen uit het blok zelf. Alle veertien staan nu op de gedeelde opmaak, met één uitzondering die er hoort te zijn (een e-mail is bewust simpel: gewone bullets, blauwe links). De poort die dit bewaakte keek alleen naar regels waar 'md' letterlijk in de opmaak stond, en ziet vanaf nu élk blok dat die klasse in de code meekrijgt." },
  { datum: "2026-08-19", tekst: "Kaarten op de klantpagina plakten aan elkaar: er stond twintig pixels tussen terwijl de ruimte tussen twee blokken vierentwintig is. Nu staat er de naam van die ruimte in plaats van een losse trede van de schaal, dus overal evenveel lucht. Ook de binnenkant van een kaart is gelijkgetrokken. En zeven pijltjes die als letter in beeld stonden (bij 'Bekijken', 'Ga erheen', 'Open pagina', 'Site-wide strategie', 'Weekplanning' en de week-vooruit-en-terug in de agenda) zijn nu getekend, want Montserrat heeft dat teken niet en dan zie je een leeg vierkantje." },
  { datum: "2026-08-19", tekst: "Een collega uitnodigen komt nu op de juiste plek uit. Vink je bij een gast precies één klant aan en heeft die klant een eigen adres, dan wijst de mail met inloggegevens daarheen in plaats van naar het dashboard met al je klanten, en staat in het teamoverzicht per gast waar hij inlogt. Dat is niet alleen netter maar ook veiliger: op dat adres bestaat er geen andere klant, ook niet als zijn rechten later verruimd worden. Daarmee is de laatste stap van de NOC-verhuizing gebouwd; er is nog één omzetting in Vercel nodig voordat het echt werkt." },
  { datum: "2026-08-19", tekst: "In de speelruimte op het scherm Stijl kun je twee standen nu naast elkaar zien, op je eigen schermen. Je kiest een richting en daarna een scherm waar je veel zit (de klantenlijst, de takenpagina van een klant, de prioriteitenscan, het financieel overzicht of de agenda), en het dashboard fotografeert dat scherm twee keer: zoals het nu is, en in de richting die je uitprobeert. Dat was de ontbrekende stap, want in je browser kan er maar één richting tegelijk aanstaan, dus vergelijken kwam neer op heen en weer klikken en het uit je hoofd doen. De foto in de nieuwe richting is precies wat vastleggen zou opleveren: hij rekent met dezelfde som als de vastgelegde huisstijl, niet met een tweede berekening ernaast." },
  { datum: "2026-08-19", tekst: "Wat je in het dossier van een lead aanlevert, ziet er later nog uit zoals het binnenkwam. Een pdf die je erin sleept wordt voortaan zelf bewaard, met zijn eigen kolommen, tabellen en beeld; de tekst wordt er daarnaast uit gehaald zodat het gesprek erin kan zoeken. Klik je op Volledig, dan zie je het origineel in beeld in plaats van een grijze lap tekst, en één knop verder alsnog de uitgelezen tekst. Een geplakte link blijft een link: hij komt in het dossier met de naam van het document en een knop die hem opent op zijn eigen plek. Lukt het lezen niet (een pdf in Drive, een map, een link naar een ander portaal), dan is dat geen foutmelding meer maar gewoon die link. En de uitlegtekst boven het gesprek is weg." },
  { datum: "2026-08-19", tekst: "Het Pagina-lab heeft zijn kennisbank: tweeëndertig criteria voor conversie, bruikbaarheid, vormgeving en interactie, te zien op het nieuwe scherm Pagina-lab onder Intern. Tot nu toe zei dit dashboard alleen iets over gevonden worden; dit is waartegen een pagina straks beoordeeld wordt op wat hij oplevert, of je hem kunt gebruiken, hoe hij eruitziet en hoe hij zich gedraagt. Bij elk criterium staat waar we naar kijken, waarom het uitmaakt, wanneer het niet opgaat, en uit welke bron het komt met de datum waarop we die bron hebben nagekeken: de toegankelijkheidsnorm van het W3C, de meetwaarden van Google, en onderzoek van Baymard, Nielsen Norman Group, Deloitte en de Spiegel-onderzoeksgroep. Daarnaast staat een aparte plank met wat wij uit ervaring vinden zonder onderzoek eronder; dat mag meewegen in een advies maar gaat nooit als onderbouwing een klantrapport in. Een proef laat de bouw mislukken als een criterium zonder bron wordt toegevoegd of als een vakoordeel zich als onderzoek voordoet." },
  { datum: "2026-08-19", tekst: "Een klant kan een eigen voordeur hebben: een tweede adres op dezelfde gegevens waar alleen die ene klant bestaat. Dat werkte al, maar je kon niet zien of zo'n voordeur ook echt naar dezelfde gegevens kijkt, en dat is juist het gevaarlijke geval: hangt hij nog aan zijn oude database, dan toont hij dezelfde klant met de gegevens van gisteren en merk je dat pas als je een dag in het verkeerde scherm hebt gewerkt. Op Intern, Verhuizen staat nu onderaan het blok 'De eigen voordeur van deze klant': adres invullen, knop indrukken, en het dashboard vraagt het aan de voordeur zelf. Groen betekent dat hij dezelfde gegevens heeft én dat het slot op die klant staat; anders staat er in gewone taal wat er nog moet. Diezelfde controle weigert voortaan ook een verhuizing naar een omgeving die dezelfde gegevens al heeft, want dat leest en overschrijft dezelfde rijen. Verder gedraagt zo'n voordeur zich nu ook als voordeur: het menu Intern toont er alleen nog de schermen die daar bestaan in plaats van vijftien links die terugkaatsen, en de meters over het hele bureau (Ahrefs-tegoed, kosten, meldingen) zijn er weg. En de verhuiscode heeft eindelijk een kopieerknop." },
  { datum: "2026-08-18", tekst: "Alle zes meters op het scherm Stijl staan op hun doel. Kleuren 40 (doel 45), lettergroottes buiten de schaal 0, afstanden 2, hoekrondingen 4, schaduwen 2, losse opmaak in de schermen 0. Op 17 augustus waren dat er 325, 21, 21, 19, 45 en 50. De laatste ronde: tien tinten grijs kregen een rol op basis van waar ze staan (tekst, rand of vlak), de laatste blauwen, groenen, paarsen en donkerroden gingen naar de kleur waar ze bij horen, en de vijf schaduwen die overbleven kregen een naam in plaats van een losse waarde. Twee daarvan gaan niet over diepte maar over richting: een zijpaneel schuift van rechts in en een balk komt van onderen, en dat hoort niet op een schaal waar de zon recht boven staat. Wat dit praktisch betekent: er is geen kleur, maat, ronding of schaduw meer die niet meebeweegt als je in de speelruimte aan de knoppen draait." },
  { datum: "2026-08-18", tekst: "Er staat geen losse opmaak meer in de schermen zelf: van 50 plekken naar nul. Dat was het lek waar geen enkele controle bij kon, want opmaak die in de React-code staat in plaats van in het stylesheet valt buiten elke regel. Wat er nog stond: de letterspatie van een klein kapitaal-kopje (die stond als 0,5 of 0,3 pixel in 47 plekken, dezelfde bedoeling twee keer geraden), de donkere balk van kijken-als, het draaiende laadrondje en het accentstreepje links van een kaart. Die hebben nu allemaal een naam. De meter telt voortaan ook eerlijker: een kolombreedte of een randje van een pixel is een indelingsmaat en geen opmaakkeuze, dus die tellen niet meer mee als werk." },
  { datum: "2026-08-18", tekst: "Derde ronde knoppen: de laatste acht eigen knopnamen zijn weg. Het gaat om de ja/nee-knoppen bij een verwijderbevestiging, het meer-knopje in het opruimscherm, de ververs-knop en de knopjes in de paginachat. Die staan nu op het knopsysteem, met de rode verwijderknop op de bestaande gevaar-variant in plaats van een eigen rood. De bewakingslijst van bestanden die nog buiten het systeem vielen ging van 57 naar 49." },
  { datum: "2026-08-18", tekst: "Nog zeven icoontjes die als letter in beeld stonden zijn nu getekend. Op de takenpagina stond een leeg vierkantje naast het knopje 'los' waarmee je het mailvenster groot opent, en hetzelfde gold voor het pijltje naar buiten bij een link, het vinkje bij een afvinklijstje, het driehoekje bij een uitklapper en het pijltje in het zijpaneel. Stuk voor stuk tekens die Montserrat niet heeft, dus kwamen ze uit een willekeurig ander lettertype of helemaal niet. Ze zijn nu allemaal kleine tekeningen die de kleur van de tekst overnemen en meeschalen met de lettergrootte, uit één gedeeld bestand zodat ze onderling dezelfde maat en uitlijning houden." },
  { datum: "2026-08-18", tekst: "Er is een scherm om een klant met alles erin naar een andere omgeving te verhuizen, te vinden onder Intern bij Beheer en controle. Bedoeld voor het Nationaal Oogcentrum, dat nog in een eigen losse cockpit stond, maar het werkt voor elke klant. Je kiest de klant, ziet eerst per soort hoeveel er staat (taken, chats, pagina's en de rest), en verstuurt daarna in één handeling; de voortgang loopt op het scherm mee. De klantkaart ontstaat vanzelf aan de andere kant, zonder inlog en zonder bedragen. Er is bewust geen lijst met soorten gegevens die iemand moet bijhouden: de verhuizing kijkt in de database zelf wat er aan een klant hangt, dus wat er later bijkomt gaat mee. Het inlezen aan de andere kant zit achter een code die de ontvangende omgeving zelf maakt, een uur geldig, versleuteld bewaard en met een klik in te trekken; zonder die code bestaat de deur niet. Twee keer verhuizen kan zonder dubbele taken." },
  { datum: "2026-08-18", tekst: "Kleuren van 96 naar 66. Er stonden negen bijna gelijke rozetinten voor de rand om een foutmelding, drie lichtgroene voor een goedmelding en drie lichtgele voor een waarschuwing; elk scherm had er ooit zelf een gekozen omdat er geen naam voor bestond. Die randen zijn nu afgeleid van de fout-, goed- en let-op-kleur zelf, dus ze veranderen mee in plaats van achter te blijven. Verder kregen twee kleuren die een soort werk aanduiden een naam: paars voor werk dat naar de developer gaat, blauw voor SEO-werk, allebei in vijf tinten verspreid. En de laatste losse groenen, bruingelen en roden staan nu op de statuskleur waar ze bij horen. Een naam in de betekenislaag mag voortaan ook een mengsel zijn ('de foutkleur met wat wit erdoor') in plaats van alleen een kale verwijzing; dat is nog steeds afgeleid van de schaal, alleen met een berekening ertussen." },
  { datum: "2026-08-18", tekst: "Eerste steen van het Pagina-lab: het dashboard kan nu elke pagina buiten dit domein ophalen én fotograferen, op desktop of mobiel, in zijn geheel of per strook. Dat was nodig omdat de Claude-omgeving alleen met dit dashboard mag praten en dus geen enkele klantpagina kon lezen of bekijken; deze server kan dat wel en draait al een browser. Een oordeel over vormgeving haal je niet uit HTML, dat moet je zien. Het lab leest mee met alles wat er al is en schrijft niets: geen tabel, geen taak, geen werklijst, en een proef laat de bouw mislukken zodra dat toch gebeurt, zodat het lopende SEO-werk er niet door kan breken." },
  { datum: "2026-08-18", tekst: "Het voor-en-na op het scherm Stijl is bijgewerkt met de stand van nu: 96 kleuren in plaats van 325, 7 schaduwen in plaats van 45, één soort knop in plaats van vijf, en geen enkele lettergrootte meer buiten de vaste schaal. De foto ernaast is opnieuw gemaakt met de opmaak van dit moment, dus wat je daar ziet is echt wat er staat en geen plaatje van gisteren." },
  { datum: "2026-08-18", tekst: "De meter voor losse opmaak in de schermen telt nu alleen nog wat een opmaakkeuze is. Hij telde ook kolombreedtes, minimale hoogtes en flex-maten mee, en dat zijn indelingsmaten die juist in het scherm horen en niet op de schaal. Daardoor was het een lijst die nooit nul kon worden, en een werklijst die nooit leeg raakt is ruis in plaats van sturing. De stand gaat daarmee van 46 naar 34, zonder dat er iets aan de code veranderd is; wat overblijft zijn echte kleuren en maten die op de schaal thuishoren." },
  { datum: "2026-08-18", tekst: "De schaduwen zijn van 45 naar 7 gegaan. De laatste dertien waren allemaal hetzelfde soort ding, namelijk iets dat boven de pagina hangt: een venster, een overlay, een menu over de inhoud heen. Die stonden los in tinten van 16 tot 28 procent zwart en met een waas van 20 tot 60 pixels, terwijl ze nooit naast elkaar op één scherm staan. Er is nu één schaduw voor een venster en één kleine donkere voor iets dat ingedrukt of actief is, en allebei bewegen ze mee met de diepte-knop in de speelruimte; als losse waarde deden ze dat niet. Daarmee is elke schaduw in het dashboard er een van zeven, en de eerste vijf daarvan zijn de vaste schaal." },
  { datum: "2026-08-18", tekst: "De statuskleuren zijn één set geworden en het doorzichtige oranje beweegt nu mee. Er waren vijf tinten groen voor 'dit is goed', vijf bruingele voor 'let op', drie roden voor 'fout' en vijf blauwen voor een verwijzing; die stonden los in de code, dus twee schermen naast elkaar toonden dezelfde melding in net een andere tint. Nu is er per betekenis één kleur, op 76 plekken. Daarnaast stonden er 31 doorzichtige oranje vlakjes (de zachte oranje achtergrond achter een actieve knop of een gemarkeerde regel) als vaste kleurcode in de opmaak; die zijn nu een mengsel met de accentkleur zelf, dus ze veranderen mee zodra het accent verandert in plaats van oranje te blijven staan. Het aantal kleuren in de opmaak ging daarmee van 129 naar 103, en het aantal schaduwen van 26 naar 19." },
  { datum: "2026-08-18", tekst: "Het dashboard kan nu ook draaien als een omgeving die maar één klant toont. Dat is de voorbereiding op de eigen NOC-voordeur: hetzelfde adres als nu, dezelfde gegevens als in het dashboard, maar met een slot erop zodat er nooit een andere klant in beeld komt bij schermdelen of bij iemand die van buiten meekijkt. Het slot werkt omgekeerd aan een lijst met verboden schermen: alles is dicht behalve de cockpit van die ene klant, dus een scherm dat er later bijkomt is vanzelf ook dicht. De klantenlijst, financiën, prognose, agenda, verbruik en teambeheer bestaan er niet, een schermfoto kan er niet buiten die klant kijken, en de nachtronden draaien er niet mee zodat werk niet dubbel gebeurt. Zolang de instelling niet aanstaat verandert er niets aan het gewone dashboard." },
  { datum: "2026-08-18", tekst: "De tweede ronde knoppen is om. De faseknoppen op het weekplan, de knoppen in het opruimscherm, de knop met de voortgangsbalk erin en de knoppen in het zijpaneel stonden nog op hun eigen opmaak; die hangen nu allemaal op het knopsysteem, met alleen nog een kleur of een toestand als eigen toevoeging. De knop met de voortgangsbalk regelt zelf nog precies één ding, namelijk die balk. Concreet betekent dit dat een faseknop op het weekplan nu even hoog is als een knop in een tabel of in een kaart, en dezelfde tekstgrootte en afronding heeft. In de opmaak zijn zestien regels verdwenen die alleen bestonden om een knop opnieuw te beschrijven." },
  { datum: "2026-08-18", tekst: "Op het scherm Stijl staat nu een voor-en-na. De meters daaronder tellen wel hoeveel kleuren, maten en schaduwen er zijn, maar een getal dat van 325 naar 129 gaat laat niet zien hoe iets eruitziet. Nu staan dezelfde vijf knoppen, dezelfde kaart en dezelfde tabel er twee keer naast elkaar: links de opmaak van 17 augustus uit de geschiedenis, rechts die van vandaag, allebei echt gerenderd en niet nagetekend. Het verschil zit vooral in de knoppen: die hadden vier hoogtes, vier tekstgroottes en drie soorten afronding, en zijn er nu nog één. Eronder staat een tabelletje met wat er per soort is samengetrokken. Meteen ook een scheve knop rechtgezet die daarbij opviel: de doorzichtige knop bleef op de oude maat staan toen de compacte knopmaat kleiner werd, dus die stond 40 pixels hoog tussen knoppen van 26. Die maat staat nu op één plek in plaats van twee." },
  { datum: "2026-08-18", tekst: "De knoppen zijn één systeem geworden. Er stonden vier oudere knopnamen naast het knopsysteem die naar dezelfde soort knop leidden maar er net anders uitzagen: ghost-btn, primary-btn, mini-btn en logout-btn, samen 419 knoppen door het hele dashboard. Die staan nu allemaal op .btn met een variant, en de oude opmaakregels zijn eruit gehaald zodat er geen tweede naam meer bestaat voor dezelfde knop. Zichtbaar: knoppen die eerst per scherm een andere hoogte, ronding of tekstgrootte hadden, zijn nu overal gelijk. De bewakingslijst van cockpit-panelen die de oude namen nog gebruikten ging van 40 naar 4 bestanden; die lijst mag alleen korter worden. Wat nog niet om is: de knoppen met een eigen functie erin, zoals de knop met een voortgangsbalk en de faseknoppen op het weekplan." },
  { datum: "2026-08-18", tekst: "De terug-pijltjes zijn nu getekende pijltjes in plaats van een letter. Een pijltje als teken hangt af van het lettertype, en Montserrat heeft er geen; dan komt het uit een ander lettertype (dus staat het er anders bij dan de tekst ernaast) of het wordt een leeg vierkantje. Een getekend pijltje erft de kleur van de tekst, schaalt mee met de lettergrootte en ziet er overal hetzelfde uit. Elf plekken omgezet: de terug-links op Verbruik, Financiën, het klantdashboard, de sitemap-check, de navigatie-roadmap, de analyse-import en het developer-overzicht, plus de doorverwijzingen in de cockpit. Pijlen die gewone tekst zijn (toen naar nu, Bestand naar Delen) blijven staan; dat zijn geen icoontjes." },
  { datum: "2026-08-18", tekst: "De lege vierkantjes waar een pijltje of een vinkje hoort te staan, zijn weg. Montserrat bevat die tekens niet, en er stond geen reservelettertype achter dat ze wél heeft; dan tekent de browser een leeg blokje of pakt hij er zelf iets bij, en dat laatste is precies waarom het ene scherm er anders uitzag dan het andere. Achter Montserrat staat nu een vaste reeks systeemlettertypes voor symbolen, en die geldt ook voor de andere lettertypes die je in de speelruimte kunt kiezen. Aan de gewone letters verandert niets: Montserrat komt nog steeds eerst en wint voor alles wat hij zelf heeft." },
  { datum: "2026-08-18", tekst: "Drie dingen die je op het scherm ziet, gerepareerd. De schermafbeeldingen op de uitlegpagina waren kapot: de foto werd als losse bytes in de database gezet in plaats van als afbeelding, dus stond er een leeg kadertje met alleen de tekst eronder. De oorzaak is een browser die tegenwoordig een ander soort gegevens teruggeeft, waarbij het omzetten naar het juiste formaat stilzwijgend niets deed. Bestaande kapotte foto's worden nu bij het tonen zelf hersteld, dus er hoeft nergens op een knop gedrukt te worden. Verder stonden de pagina's Verbruik en Financiën volledig in een ander lettertype dan de rest van het dashboard (het systeemlettertype in plaats van Montserrat), en dat viel op zodra je van het ene scherm naar het andere ging. En het lettertype voor code, paden en sleutels stond in zes verschillende varianten door de opmaak heen; dat is er nu één. Daarmee staat er geen enkele lettergrootte meer buiten de vaste schaal." },
  { datum: "2026-08-18", tekst: "Vier dingen. (1) Rechts op elke taakregel staat nu een keuzelijstje met vier standen: gepland, bij developer, bij klant, afgerond. Daar stond alleen het woord gepland, dus je las de stand wel maar kon hem niet zetten. Kies je bij developer, dan komt de kaart ook echt op de developerlijst; kies je een andere stand, dan gaat hij eraf. (2) Afgerond haalt de taak uit de lijst en zet hem onderaan in een blok Afgeronde taken dat dicht begint, plus met datum in Wat we doen. Terugzetten kan vanuit dat blok, en direct na het afvinken staat er bovenaan nog een regel met een knop Terugzetten. Het losse vinkje van vanochtend is hierin opgegaan, want twee knoppen voor afgerond in dezelfde regel is er een te veel. (3) Het vraagveld bij Laatste mails leest nu dezelfde mailbox als de lijst eronder. Het las alleen opgeslagen mail, en die tabel wordt sinds de Microsoft-koppeling niet meer gevuld, dus kreeg je er hangen nog geen mails in het dashboard voor deze klant terwijl er tientallen mails naast stonden. (4) Bij een developertaak met een opmerking staat nu een zichtbaar linkje Bekijk de opmerkingen dat de taak opent, in plaats van een stipje dat niemand zag; de tekst zelf blijft uit de lijst. En in het opmerkingenveld kun je een afbeelding of document slepen: dat gaat naar de Drive-map van de klant en hangt daarna bij Documenten en bestanden van die taak." },
  { datum: "2026-08-18", tekst: "Het dashboard kan nu zelf zien of een opmaakronde iets zichtbaars heeft gedaan, en daarmee gaat dat werk voortaan door zonder er telkens naar te hoeven kijken. Er lag al een route waarmee elk scherm zichzelf fotografeert; die wordt nu gebruikt om tien schermen voor en na een ronde te vergelijken. Twee getallen komen eruit. Het eerste telt de pixels die anders zijn, en dat getal blijkt onbruikbaar zodra er data bij komt: de klantenlijst stond meteen op 12 procent omdat er ondertussen klanten waren bijgewerkt, terwijl er aan de opmaak niets veranderd was. Het tweede vergelijkt hoevéél van elke kleur er op het scherm staat in plaats van waar, en dat is blind voor verschoven inhoud maar gevoelig voor een rand, een schaduw of een tint die verandert. Onder een half procent gaat een ronde door zonder overleg, tussen een half en drie procent met een foto erbij, daarboven eerst laten zien. Een nieuw ontwerp of een andere indeling valt hier niet onder; dit gaat alleen over strak trekken binnen de stijl die er is." },
  { datum: "2026-08-18", tekst: "Kleuren van 158 naar 129 en schaduwen van 34 naar 26, plus de pixelmaten die in de schermen zelf stonden op de schaal. Dit is de eerste ronde die volgens de nieuwe werkwijze doorging: alles achter elkaar, één keer gemeten, geen tussentijdse vraag. De meting achteraf gaf op de stabiele schermen tussen 0,00 en 0,33 procent kleurverschil, dus er is niets aan het gezicht van een scherm veranderd. Wat er wel gebeurde: 157 plekken in de opmaak en 22 in de schermen kregen een naam in plaats van een losse kleurcode, en de laatste pixelmaten in vier schermen staan op de ruimte-, tekst- en rondingsschaal. Daarmee bewegen ook die plekken mee zodra er ooit aan het accent, de ruimte of de diepte gedraaid wordt." },
  { datum: "2026-08-18", tekst: "De richting is gekozen: het dashboard blijft eruitzien zoals het nu is. Daarmee verschuift het werk van 'hoe wordt het' naar 'geldt het overal', en die ronde is nu gedaan voor schaduwen en voor de kleuren die los in de schermen stonden. Schaduwen: van 45 verschillende naar 34, met een stap erbij op de schaal voor de zachte waas die acht keer net anders was opgeschreven. Kleuren: 51 plekken in acht schermen die een kleurcode rechtstreeks in de code hadden, staan nu op een naam; ruim de helft daarvan was letterlijk dezelfde kleur als een naam die al bestond. Zichtbaar verandert er niets: dertien schaduwen verschuiven een pixel of een honderdste doorzichtigheid, en geen enkele kleur springt verder dan het punt waarop je een verschil begint te zien. Wat het oplevert: die plekken bewegen nu wél mee als er ooit aan het accent of de diepte gedraaid wordt. Wat bewust blijft staan: 19 schaduwen en ruim honderd kleuren die echt anders zijn, want daar zit een keuze in en die hoort op het scherm Stijl, niet in een script." },
  { datum: "2026-08-18", tekst: "Twee dingen die niet deden wat ze beloofden. (1) Het grijpvlekje om een regel te verslepen in een tekstveld (de koers, het overzicht, je aantekeningen) verscheen keurig als je over de tekst zweefde en verdween precies op het moment dat je hem wilde pakken. De oorzaak: onderweg naar links kom je door de inspringing van een lijst, en daar staat geen regel maar het lege tekstvak, dus dacht het scherm dat je nergens meer boven zweefde. Er wordt nu op de hoogte van je muis gekeken in plaats van alleen recht eronder, en een browsertest loopt die weg voortaan stap voor stap na, want met een muis die in een keer op het vlekje springt is dit onzichtbaar. (2) De knop Delen met developer bij de bedrijfsgegevens maakte een taak aan die nooit op de developerlijst kwam: hij kreeg de stand Gepland en die lijst toont alleen wat op Naar dev staat, dus de mail verwees naar een lijst waar niets stond. Daaronder zat een diepere fout: bij het aanmaken van een taak werden drie velden wel meegegeven en stil niet opgeslagen, waaronder het kenmerk waarmee elke motor zijn eigen vorige taak herkent. Daardoor kwam er bij elke klik een kopie bij (bij Bogard stonden er vier) en misten die taken ook het document dat erbij hoort. Dat gold ook voor structured data per pagina, interne links en de cannibalisatie-redirects." },
  { datum: "2026-08-18", tekst: "Een stijl die je in de speelruimte kiest, kun je nu vastleggen met één knop. Tot nu toe kon je op /admin/stijl draaien aan de accentkleur, het lettertype, de ruimte, de tekstgrootte, de ronding en de diepte, en zag je dat meteen op elk beheerscherm, maar alleen in je eigen browser: de laatste stap was altijd \"zeg maar welke, dan zet ik hem door in de code\". Die stap is weg. Onderaan de speelruimte staat nu 'Leg deze stijl vast voor iedereen'; daarna is het gewoon hoe het dashboard eruitziet, ook in het klant-dashboard, en 'Terug naar de standaard' zet alles in één klik terug. De stijl wordt in de kop van elke pagina meegestuurd, dus je ziet nooit eerst even de oude stijl staan. Wat er bewust niet in zit: dit stuurt alleen de handvol tokens waar de speelruimte over gaat, niet de opmaak zelf, en alleen jij als eigenaar kunt het vastleggen. Waarom het niet in de code zit: een keuze die een bouw nodig heeft wordt niet gemaakt op het moment dat je hem maakt, en een ander bureau dat dit dashboard straks gebruikt kan niet bij de code." },
  { datum: "2026-08-18", tekst: "Vijf dingen rond taken en mail. (1) Naast Superhuman staat in elke mailregel een knopje Taak: dat maakt van die mail meteen een kaart in de planning, met een korte titel die zegt wat er moet gebeuren, een beschrijving van twee of drie zinnen in het bestaande veld Aantekeningen, en de link naar de mail eraan vast. Bewust geen nieuw veld erbij. (2) Slepen werkt nu ook bij Nog geen datum. Daar zag je wel de oranje streep waar de taak zou komen, maar bij loslaten sprong hij terug: de volgorde werd berekend binnen een week, en een taak zonder datum heeft geen week die ergens op slaat, dus de som stopte er stilzwijgend mee. (3) Links op elke regel staat een vinkje om een taak af te vinken, zonder de kaart open te klappen; hij blijft bovenaan nog even staan met een knop Terugzetten. (4) Een afgevinkte taak komt met datum bij Wat we doen te staan, ook de taken die daar al op klaar stonden; daarvoor verdween een afgevinkte taak van het scherm en stond nergens meer dat hij gebeurd was. (5) Bij Wat we doen staat nu ook de correspondentie zelf, live uit de mailbox in plaats van alleen uit wat ooit was opgeslagen, door dezelfde zeef als Laatste mails zodat er geen nieuwsbrieven tussen komen. En onderaan de mailkolom haalt Meer mails er telkens twintig bij." },
  { datum: "2026-08-18", tekst: "De laatste losse maten staan nu op de vaste schaal: 1.011 plekken. Het aantal verschillende afstanden gaat van 21 naar 2, tekstmaten van 16 naar 1, hoekrondingen van 18 naar 4. Dit zie je wel, want afstanden verschuiven maximaal twee pixels: een marge van 10 wordt 8, een van 6 wordt 4, een van 18 wordt 16. Wat verder zou moeten springen is blijven staan. Een maat wordt nooit nul: 2 pixels padding werd bijna 0 (even ver van 0 als van 4), wat de padding van elk labeltje en elke pil zou hebben laten verdwijnen; die worden nu 4. Hiermee is de opruiming rond: van alle opmaak leest 85 procent uit de betekenislaag en van de rest bijna alles uit de schaal eronder. Praktisch betekent dat: als je in de speelruimte aan ruimte, tekstgrootte of ronding draait, beweegt nu vrijwel het hele dashboard mee in plaats van driekwart." },
  { datum: "2026-08-18", tekst: "Elk veld in de bedrijfsgegevens houdt nu zijn eigen datum bij, in plaats van een datum voor het formulier als geheel. Dat is veiliger: met een datum voor alles verzet je met een keer opslaan de grens voor elk veld, en dan verliest een klantdocument van vorige week ineens van een adres dat je nooit hebt aangeraakt. Nu weet elk veld voor zichzelf wanneer die waarde er kwam en wie hem zette, jij of een aangeleverd stuk. Sla je het formulier op, dan krijgen alleen de velden die echt veranderd zijn de datum van nu. Bij een vestiging of een arts hangt de datum aan de rij zelf, aan de postcode of het BIG-nummer, dus sleep je een vestiging naar boven dan verhuizen de datums mee in plaats van bij de buurman te blijven hangen. Voor gegevens van voor vandaag geldt de laatste opslag van het formulier als ondergrens, tot ze een keer bijgewerkt worden." },
  { datum: "2026-08-18", tekst: "Het versiebeheer op datum is doorgetrokken naar het formulier Bedrijfsgegevens. Tot nu toe gold de datumregel alleen in de kennisbank en werd het formulier ernaast alleen aangevuld waar het leeg was, dus stuurde een klant nieuwe openingstijden, dan nam de kennisbank die over en bleef in de velden de oude tijd staan. Nu vervangt een gegeven uit de kennisbank ook een ingevulde waarde, mits het aantoonbaar nieuwer is dan de laatste keer dat je het formulier hebt opgeslagen: wat je zelf invult wint dus, tot er materiaal komt van na jouw wijziging. Zonder datum op het materiaal verandert er nog steeds niets aan een ingevuld veld, en een leeg veld wordt gewoon gevuld zoals altijd. Wat er vervangen is verschijnt na afloop in een groen blok met de datum erbij, want het dashboard doet dit zonder dat je het vraagt en dan hoor je te zien wat er veranderde. Een beperking om te weten: het formulier houdt een datum bij voor het geheel en niet per veld, dus een keer opslaan verzet die grens voor alle velden tegelijk." },
  { datum: "2026-08-18", tekst: "Het aantal kleuren in het dashboard is gehalveerd en meer: van 325 naar 168. 166 kleuren die geen naam hadden zijn samengevoegd met de kleur die er al een naam heeft, op 465 plekken. Het gaat om tinten die je met het blote oog niet uit elkaar houdt: acht bijna-witten, elf bijna-grijzen, een handvol bijna-dezelfde rood- en oranjetinten. De grootste verschuiving is 28 op een schaal waar 30 het punt is waarop je een verschil begint te zien, dus in de praktijk verandert er niets zichtbaars; twee schermen zijn voor en na vergeleken. Dit is wel echt iets anders dan de omzettingen van vandaag: daar veranderde de waarde niet, hier wel, alleen zo weinig dat het niet opvalt. Wat overblijft zijn 48 kleuren die duidelijk dezelfde familie zijn maar een andere tint, en 53 die echt anders zijn. Die staan op het scherm Stijl met een staaltje erbij, want daar zit een keuze in en die is niet aan een script. Het belang: elke kleur die nu een naam heeft, beweegt mee als je in de speelruimte een ander accent kiest. Elke kleur zonder naam blijft staan waar hij staat." },
  { datum: "2026-08-18", tekst: "Een schermafdruk met alleen openingstijden landt nu op de bestaande vestiging in plaats van ernaast. Zo'n afdruk noemt per vestiging alleen de naam en de tijden, terwijl een vestiging herkend wordt aan postcode plus huisnummer. Daardoor kwamen er tien nieuwe, adresloze regels naast de bestaande te staan, en die telden nergens mee omdat iets zonder bezoekadres geen vestiging is: de tijden kwamen dus wel binnen en toch nergens aan. Draagt het aangeleverde stuk zelf geen adres of BIG-nummer, dan wordt er nu op naam gekoppeld, maar alleen als er precies een naamgenoot is. Zit er wel een adres bij, dan gebeurt dat niet, want twee vestigingen van dezelfde keten mogen nooit stilletjes samenvallen. Dezelfde regel geldt bij het ontdubbelen, zodat regels die eerder los kwamen te staan alsnog bij hun vestiging landen." },
  { datum: "2026-08-18", tekst: "Een stijl die je op de stijlpagina kiest, geldt nu op het hele dashboard terwijl je hem uitprobeert. Je kiest een richting of draait aan de knoppen, loopt naar je takenpagina, je klantkaart of je agenda, en je ziet daar echt hoe het uitpakt. Bovenin staat een balkje dat zegt dat je naar een proefstijl kijkt, met welke, en met een knop om alles terug te zetten. Dat balkje is niet optioneel: een proef die je niet kunt zien lopen zou betekenen dat je op een dag naar een dashboard kijkt dat er voor jou anders uitziet dan voor iedereen anders, zonder dat te weten. De proef leeft alleen in jouw browser; een klant of collega ziet er niets van, en pas als een richting bevalt gaat hij via de code echt live voor iedereen." },
  { datum: "2026-08-18", tekst: "Op het scherm Stijl staat nu een speelruimte, en dat is waar de hele verbouwing voor was. Je kiest een richting (zoals het nu is, strak en zakelijk, zacht en luchtig, of rustig en datadicht) of je draait zelf aan zes knoppen: accentkleur, lettertype, hoeveel ruimte, hoe groot de tekst, hoe rond de hoeken en hoe diep de schaduwen. Het hele scherm verandert mee terwijl je kijkt, en niet in een los voorbeeldblokje: de kopbalk, de kaarten, de knoppen, de tabellen en de meters die je daar ziet zijn precies dezelfde bouwstenen als op elk ander scherm. Dat kan pas sinds alles uit dezelfde handvol namen leest; drie maanden geleden had een andere accentkleur betekend dat je 331 plekken langs moest. Het legt niets vast: je speelt in je eigen browser en bij het verlaten van de pagina staat alles weer zoals het was. Bevalt een richting, zeg welke, dan gaat hij echt door voor het hele dashboard. Ook het lettertype staat nu op een naam in plaats van 48 keer los uitgeschreven, want anders was omschakelen 48 plekken langslopen." },
  { datum: "2026-08-18", tekst: "Het dashboard bepaalt nu zelf welke versie van een gegeven geldt, op datum, in plaats van dat jij ergens een vinkje moet zetten. Het leest van elk aangeleverd stuk af van wanneer de inhoud is: Word, Excel en pdf bewaren wanneer ze voor het laatst zijn opgeslagen, een foto wanneer hij genomen is, van een Google-document weet Drive het, en een mailbijlage is nooit jonger dan de mail. Pas als daar niets staat telt de datum van het bestand zelf. Vergelijken gebeurt per gegeven en niet per document, dus een schermafdruk van alleen de openingstijden gooit het adres niet weg, en een waarde die gelijk blijft houdt zijn oorspronkelijke datum zodat een controle-ronde onze eigen gegevens niet verjongt. Is er nergens een datum te vinden, dan wordt er niets overschreven: dat materiaal vult alleen lege plekken aan, en onder het voorstel staat wat er niet is overgenomen en waarom. Bij elk gegeven in de kennisbank zie je nu van wanneer het is en waar het vandaan komt. Op een taakkaart is de keuze bij structured-data-documenten verdwenen, want daar is de kennisbank wat geldt en zijn de bestanden het archief; die regel linkt er nu heen. En van elk document in de lijst zie je nu de datum van het document zelf in plaats van het moment waarop het binnenkwam, met een klik op de regel wat erin staat." },
  { datum: "2026-08-18", tekst: "De uitleg-bolletjes die bij hover verschijnen, springen niet meer meteen in beeld. Je moet nu eerst kort stil blijven hangen (zeven tienden van een seconde) voordat er iets opkomt. Beweeg je gewoon met je muis over het scherm, dan gebeurt er niets meer, terwijl er eerst bij elk knopje dat je passeerde een zwart schermpje opflikkerde. Dat geldt ook voor de voorvertoning van een link in de werklijst, die bovendien pas dan een Google-document begint te laden in plaats van bij elke link waar je langs komt. Twee dingen blijven direct: met het toetsenbord naar iets toe springen toont de uitleg meteen, en klikken laat hem meteen vallen. De wachttijd staat op één plek, dus hij is met één getal korter of langer te zetten." },
  { datum: "2026-08-18", tekst: "Het hele dashboard is in een keer omgezet naar de betekenislaag: alle 173 groepen schermen tegelijk. Van alle opmaak leest nu 84,7 procent uit de nieuwe laag, was 38,5. Er verandert niets aan hoe het eruitziet; alle 4.232 stijlregels zijn nagerekend met alle verwijzingen opgelost, en er komt nergens iets anders uit. Onderweg bleek het gereedschap een gat te hebben: het had geen geheugen, dus bij een tweede ronde over hetzelfde scherm zette het precies de namen terug die er de vorige ronde met de hand waren uitgehaald. Een lijst-inspringing ging weer kaartpadding heten, lopende tekst ging weer kaartkop heten. Er is nu een lijst met 37 plekken die bewust geen naam krijgen, elk met de reden erbij: negen stukken lopende tekst, tien inspringingen, acht kruisjes en prullenbakjes, zes codes en vier getallen die niet in de cijfermaat passen. Het gereedschap leest die lijst en laat ze met rust." },
  { datum: "2026-08-18", tekst: "Tien schermen tegelijk om naar de betekenislaag: het overzicht-tabje, developer, de werklijst, de pagina-chat, werkzaamheden, het Google-bedrijfsprofiel, de routekaart, de prognose, de KPI-tabellen en de prioriteitenlijst. Samen 653 regels opmaak. Van alle opmaak in het dashboard leest nu 38,5 procent uit de nieuwe laag, was 18,5. Er verandert niets aan hoe het eruitziet, en dat is doorgerekend in plaats van gefotografeerd: alle 4.232 stijlregels naast elkaar, per stuk nagerekend, nul verschil. Dat tien schermen nu in een ronde kunnen in plaats van een per keer komt doordat de omzetting gereedschap is geworden, met de twee fouten uit de eerste ronden erin gecodeerd. Vijf namen zijn met de hand beoordeeld: twee grote getallen kregen de cijfer-rol, en drie dingen die geen kop en geen getal zijn (twee codes en een uitgelicht woord) staan bewust zonder naam, want geen naam is beter dan een verkeerde." },
  { datum: "2026-08-18", tekst: "Het opruim-scherm (cannibalisatie en opruimlijsten) leest nu ook uit de betekenislaag, net als de agenda en de takenpagina. 170 regels om, en er verandert niets aan hoe het eruitziet; dat is deze keer niet met een foto gecontroleerd maar met een berekening die alle 4.232 stijlregels in het dashboard naast elkaar legt en per stuk narekent of er hetzelfde uitkomt. Nul verschil. Van alle opmaak leest nu 18,5 procent uit de nieuwe laag, was 12,8. Twee namen bleken onderweg niet te kloppen en zijn teruggedraaid: lopende tekst in een kaart heette even kaartkop, en een groot getal heette even paginakop. Voor dat laatste is er nu een eigen naam. Een verkeerde naam is erger dan geen naam, want dan verschuift er straks iets mee dat er niet bij hoort." },
  { datum: "2026-08-18", tekst: "309 maten in het dashboard staan nu op de vaste schaal. Twee soorten: 235 plekken waar de tekst een halve pixel verschuift (12 en 13 pixels worden allebei 12,5), dat ziet niemand, en 74 hoeken van 8 pixels rond die 6 worden, dat zie je wel: knoppen, kaarten en balkjes zijn iets minder rond geworden. Daarmee zakt het aantal verschillende tekstmaten van 21 naar 16. Bovenaan het scherm Stijl staat nu ook waar we zijn in de verbouwing, in vier stappen: tellen wat er is, namen geven, elk scherm die namen laten gebruiken, en pas daarna het ontwerp kiezen. De eerste drie veranderen niets aan hoe het dashboard eruitziet; ze maken alleen mogelijk dat de vierde in een keer kan in plaats van honderden plekken langs te lopen. Dat stond tot nu toe alleen in losse chats, en dat scroll je kwijt." },
  { datum: "2026-08-18", tekst: "Op het scherm Stijl staat er een blok bij: Wat nog niet past. Het opruimen van de opmaak valt namelijk in twee heel verschillende soorten werk, en dat verschil was tot nu toe onzichtbaar. Een kleur die al een naam heeft die naam geven verandert niets, dat kan gewoon door. Maar een tekst van 13 pixels bestaat niet in de vaste schaal, dus die wordt 12,5 of hij blijft 13, en dat is een keuze en geen rekensom. Achtendertig maten passen niet, samen 564 plekken. Ze staan nu op twee stapels: wat je ziet (een verschil van een hele pixel of meer, zoals een hoek van 8 pixels rond die 6 wordt, 74 plekken) en wat niemand ziet (een halve pixel, zoals 13 pixels tekst die 12,5 wordt). Elke maat wordt getekend zoals hij er nu uitziet en zoals hij zou worden, naast elkaar, met erbij hoe vaak hij voorkomt en waar hij staat. Zo hoef je niet op een getal te vertrouwen maar kun je het zien. Een afwijkende maat mag blijven, als het een besluit is en geen restje." },
  { datum: "2026-08-18", tekst: "De werklijst voor de sitebouwer is versmald tot waar hij voor bedoeld was: alt-teksten. De meta-titles en -descriptions stonden er ook op, en die zijn eruit. Ze ontstaan en worden goedgekeurd op het tabje Meta & CTR, en daar staat ook de knop om ze op de site te zetten; ze stonden dus met dezelfde goedkeuring op twee schermen, met op allebei een doorvoerknop, en dan weet je nooit welke telt. Alt-teksten blijven er wel op, want die ontbreken op tientallen pagina's tegelijk en dat wordt nooit een stapel losse kaartjes; er staat er nu precies een per afbeelding, want zo bewaart WordPress hem ook. Het Word-document in Drive is ook weg: een lijst van tientallen regels in een document leest niemand en afvinken kan er niet in, terwijl de deelbare afvinkpagina wel bijhoudt wat af is en of het echt op de site staat. De knop op de takenpagina heet nog hetzelfde en linkt nu naar die pagina in plaats van naar een document. Wat er nieuw bij komt: een ruw signaal per pagina, hoeveel foto's daar het onderwerp van die pagina laten zien; dat stond verstopt in de kop van het meta-blok en heeft nu een eigen blok." },
  { datum: "2026-08-18", tekst: "Stap twee van het strak trekken: de tokens hebben nu een betekenis. Tot nu toe zei het fundament alleen hoe groot iets is en welke kleur het heeft. Dat is genoeg om consequent te zijn en te weinig om iets te kunnen veranderen: wil je alle bijschriften een tikje groter, dan moet je weten welke van de honderden gebruiken een bijschrift is, en dat stond nergens. Er liggen nu zevenenveertig namen bovenop die zeggen waarvoor een waarde dient, zoals een bijschrift, een kaartrand of de ruimte binnen een kaart. Of dat bijschrift 12,5 of 13 pixels is, staat vanaf nu op een plek. De namen volgen hoe het al gebruikt werd en niet hoe het zou moeten heten; dat is eerst nageteld, bijvoorbeeld dat de grijze kleur 398 keer als tekst staat en een keer als vlak. De gedeelde bouwstenen (kaart, knop, label, rij) staan er meteen op, dus elk scherm dat die gebruikt erft de betekenis mee zonder zelf verbouwd te worden. Er verandert visueel niets: twee schermen zijn voor en na de wijziging gefotografeerd en zijn pixel voor pixel identiek. Naast het plafond op het aantal losse waarden staat nu een vloer onder het gebruik van die laag, die alleen mag stijgen, want een laag die niemand gebruikt is geen fundament maar een stapel ernaast. En een les die een oplevering kostte: de knopmeter telde classnamen en zag een keurige knop met een aan-stand en een pijltje erin aan voor drie nieuwe soorten knop. Hij hield daarmee goed werk tegen en de site stond een middag stil op de vorige versie. Die meter houdt nu geen bouw meer tegen, want dat een knop het knopsysteem gebruikt werd al ergens anders bewaakt." },
  { datum: "2026-08-18", tekst: "De takenpagina is opgeruimd. De knop 'Ruim alle kaarten op' is weg: die liet de assistent in één klik tot twintig kaartteksten herschrijven, en dat was reparatiewerk voor de kaarten uit de begintijd. Die zijn op, nieuwe kaarten komen al netjes binnen, en bij het samenvoegen van twee kaarten over dezelfde pagina wordt de tekst nog steeds vanzelf opgeschoond. Het knopje dat ditzelfde per kaart deed was om precies die reden al eerder verdwenen; de route erachter is nu ook opgeruimd, zodat er geen dode motor blijft liggen. Verder is de regel in de planning rechtgezet: het kruisje om een taak weg te halen stond als een brede knop in beeld, doordat er in het kolomraster nog een kolom stond van de badge SEO/DEV die er in augustus uitging, waardoor alles één plek opschoof. Het is weer een klein kruisje rechts. De kop van de lijst zegt nu 'Open' met het aantal in een grijs bolletje, dezelfde vorm als 'Nog geen datum' eronder, en 'Taak toevoegen' heeft dezelfde compacte maat als de andere knoppen. En 'Waar we naartoe werken' staat bovenaan de rechterkolom, op dezelfde hoogte als 'Overview' links, met de mails en het vrije overzichtsveld eronder." },
  { datum: "2026-08-18", tekst: "Er is een nieuw scherm Stijl (Intern-menu), en het is met opzet ongemakkelijk. Bovenaan staat hoe weinig keuzes dit dashboard zou moeten hebben: een schaal voor tekst, een voor ruimte, een set kleuren met een naam, en vier soorten knop. Daaronder staat wat er werkelijk in de code staat, en dat zijn er honderden. Dat was tot nu toe onzichtbaar: er waren al drie controles op de opmaak en die stonden alledrie groen, want die vragen of een scherm zich aan de regels houdt, niet hoeveel verschillende kleuren en maten er in totaal bestaan. Honderd schermen die allemaal netjes een eigen kleur kiezen leveren honderd kleuren op. Elke losse kleur wordt op dat scherm naast de kleur gelegd die al een naam heeft, en dan blijkt het grootste deel geen ontwerpwerk maar opruimwerk: dezelfde kleur anders opgeschreven, of een tint die je met het blote oog niet van de bestaande kunt onderscheiden. Er is nu ook een meter bij de bouw die alleen mag dalen: verzint iemand een nieuwe kleur, tekstmaat of schaduw buiten de schaal om, dan komt het niet live, en ruim je op dan zakt het plafond mee zodat het er niet later weer in glipt. Die meter betrapte meteen het nieuwe scherm zelf, dat twee eigen knopnamen had verzonnen; die zijn eruit. Er verandert nog niets aan een bestaand scherm: dit is de nulmeting en de testbank waarop je straks een nieuw ontwerp kunt proberen." },
  { datum: "2026-08-18", tekst: "De projectkaart is opnieuw ingedeeld. Alles over de developer is nu één knop in de Implementatie-rij: hij vraagt 'Naar developer?', opent het doorzet-venster met de documenten, en zodra de kaart op de developerlijst staat is diezelfde knop rood en zegt hij 'Bij developer'. Die stand stond op vier plekken tegelijk (een knop, een vinkje, de statuspil rechts en nog een knop onderaan); de pil rechts gaat weer alleen over de fase zelf. Onderaan de kaart zijn de Mail-knop en de link naar de live pagina weg, want die staan al in de Implementatie-rij en bovenaan in de titel; bij een taak zonder pagina blijven ze staan, want die heeft geen fase-rij. De knop Pagina's staat nu rechts van Chat over deze pagina, in dezelfde vorm. De verse meting staat rechts op de kopregel naast Over deze pagina in plaats van als losse balk erboven. En Achtergrond en afspraken, Documenten en Oude versies van deze kaart zijn drie knopjes in één rij boven je aantekeningen: klik je er een open, dan vult die de hele breedte en gaat de vorige dicht. Een controle vóór elke bouw houdt dit zo." },
  { datum: "2026-08-18", tekst: "Het dashboard is op acht plekken sneller gemaakt, gemeten in plaats van geschat. De grootste: het tabblad Resultaten deed er tien seconden over bij One Day Clinic en eenendertig bij Kamsteeg, omdat het bij elke keer openen opnieuw het hele Google Analytics-account afliep om te zoeken naar een koppeling die er niet is, en dat twee keer per keer. Dat wordt nu hooguit één keer per week herhaald; koppel je Analytics alsnog, dan wordt het vanzelf gevonden. Van tabblad wisselen vroeg ook elke klik opnieuw de hele pagina op bij de server (ruim een seconde, alleen om het adres in de adresbalk bij te werken) en doet dat niet meer. Een tabblad dat je bezocht hebt blijft nu staan in plaats van weggegooid te worden, dus terugkomen kost niets meer en je filters en uitgeklapte rijen staan er nog; een scan die je gestart hebt loopt door terwijl je ergens anders kijkt. Meta & CTR opende in acht tot achtentwintig seconden omdat het eerst de pagina's van de klant ging ophalen om te controleren of goedgekeurde meta's al live stonden; die controle gebeurt nu ná het tonen. Het developer-scherm bouwde zijn tabel bij elke vraag opnieuw op, ruim honderd overbodige opdrachten per keer. Verder: het Resultaten-tabblad vraagt bij het openen nog één keer om zijn gegevens in plaats van vijf keer, de cockpit van een klant wordt al klaargezet zodra je zijn naam aanwijst in de kiezer, alle eenenvijftig tabellen worden nog maar één keer per database aangemaakt in plaats van bij elke koude server, en het toegangsbewijs voor Google wordt hergebruikt zolang het geldig is in plaats van bij elke vraag opnieuw opgehaald." },
  { datum: "2026-08-18", tekst: "Zes kleine dingen rechtgezet op de takenpagina en in de developerlijst. Terug vanaf Navigatie & voortgang gaat naar Taken in plaats van naar Pagina's, want dat is het scherm waar je vandaan komt. Een taak van de developerlijst halen doe je nu met een kruisje achter Bekijk, Mail en Controleer, zoals overal elders in het dashboard, met dezelfde vraag om bevestiging. Het klokje herinner me over X dagen is bij elke taak weg: een taak heeft al een datum, en die extra wekkers maakten van de takenlijst een tweede lijst om af te werken. In de Implementatie-rij stond drie keer hetzelfde over de developer (een knop, een vinkje en de statuspil rechts); daar is één vinkje Bij dev van over, en het pakket met opdracht en documenten doorzetten blijft de knop onderaan de kaart. Concept in site heet nu Maak concept. En de twee vakken Waarom deze pagina en Aanpak en afspraken staan achter één dichte regel Achtergrond en afspraken: dat is bevroren tekst uit de dag dat de kaart gemaakt werd, dus de posities erin kloppen na een paar weken niet meer, maar hij reist wel als sturing mee naar de chat en de documenten en mag daarom niet onzichtbaar worden." },
  { datum: "2026-08-18", tekst: "Drie dingen recht gezet in het taakvenster van de developer. Opmerking voor de developer is nu echt jouw veld en begint leeg; er stond automatisch de bouw-regel in die de chat bij de projectkaart had bedacht, dus je opende het venster met een lap tekst die je eerst moest weggooien. Die kaarttekst staat nu als apart, netjes opgemaakt blok erboven, met een knop Overnemen als je hem juist wel als basis wilt. Het kruisje bij een document haalt hem er nu echt af: dat deed niets, omdat de meeste documenten niet zelf toegevoegd zijn maar door het dashboard bij de pagina gevonden worden (de pagina, de copy, de blauwdruk, de analyse) en dus elke keer opnieuw boven water kwamen. Elke taak houdt nu bij wat er niet meer bij hoort; het document zelf blijft gewoon bestaan en blijft bij de pagina staan. En een taak van de lijst halen kan nu uit de rij zelf, naast Bekijk, Mail en Controleer, met dezelfde vraag om bevestiging; daarvoor moest je voor de meest gebruikte handeling eerst een venster openen." },
  { datum: "2026-08-18", tekst: "De takenpagina is korter. De bespreeklijsten staan er niet meer op: dat blok gaat over wat je met wie wilt bespreken, niet over wat we deze periode doen. De knop Klopt dit nog bij de koers is weg, samen met de route erachter; bij Kamsteeg leverde een klik vijf opmerkingen op die nergens over gingen, en een controle die je moet wegdenken kost aandacht zonder iets terug te geven. De dubbele lijn boven de koers is daarmee ook verdwenen. De koers en Waar het werk vandaan komt zitten allebei achter een uitklapper die dicht begint, net als Laatste mails, want een koers is vaak een heel strategiestuk en opengeklapt duwt die de planning en de gesprekken van het scherm af. Wat je openzet blijft per klant onthouden. De kop met het vlaggetje blijft staan." },
  { datum: "2026-08-18", tekst: "De strook Wat we nu oppakken is van de takenpagina af, met alles wat eromheen gebouwd was: de knop Bijwerken, de rode seintjes dat er daarna nog iets besloten was, en de knop Dit klopt al. Dat waren vier mechanismen voor één veld dat je toch met de hand bijhoudt, en het werkte verkeerd om: bij Kamsteeg stond er een strategie in die op 5 augustus klopte en op 16 augustus herzien was, met vier rode uitroeptekens erboven waarvan er een naar precies dat ingehaalde gesprek wees. Er zijn nu drie lagen die elkaar niet overlappen: de koers is de grote lijn in je eigen woorden, de knoppenrij eronder laat zien waar werk klaarligt, en de planning is wat we deze periode doen. De koers staat voortaan gewoon open in plaats van achter een uitklapper, en je vult hem door te knippen en te plakken uit een gesprek of uit Overzicht. De assistent leest voortaan de koers mee in plaats van dat oude lijstje, dus hij krijgt geen verouderd beeld meer door. De oude tekst is niet weg: die staat nog in de opslag en in de versiehistorie op Veld terugzetten. Verder twee kleine dingen bij de gesprekken: elk onderwerp toont nu de datum van het laatste bericht, met het laatst gewijzigde bovenaan, en elk onderwerp is nu echt te verwijderen met het kruisje, ook Algemeen; die werd bij elke keer laden opnieuw aangemaakt en bleef dus staan." },
  { datum: "2026-08-17", tekst: "De takenpagina en de projectkaart zijn opgeruimd. Het vrije tekstveld dat 'Zoekwoorden & links' heette, heet nu Overzicht en staat weer op Taken, in de rechterkolom onder de mails en boven Waar we naartoe werken; op het dossier staat het niet meer, want één veld hoort op één plek. In de Implementatie-rij van een kaart staat er een knop bij: Concept in site zet de geldende copy als concept-pagina in de site van de klant, waarbij de live pagina ongemoeid blijft en publiceren jouw klik in WordPress blijft. Diezelfde knop stond onderin de documentenlijst bovenaan de kaart, ver van de stap waar hij bij hoort, en is daar weg. Naast Developer staat nu een vinkje (ligt bij dev) waarmee je alleen de stand zet zonder iets door te sturen; het schrijft dezelfde stand als die knop, dus de kaart en de developerlijst kunnen niet uit elkaar lopen. De knop Gedaan heet nu Gedaan? omdat hij een vraag stelt aan de live pagina in plaats van zomaar af te vinken. Twee knoppen in de kaartkop zijn weg: Is dit doorgevoerd? deed exact dezelfde meting als Gedaan?, en Opschonen herschreef kaarttekst in het oude formaat, wat niet meer nodig is nu die kaarten opgeruimd zijn en nieuwe al goed binnenkomen." },
  { datum: "2026-08-17", tekst: "Alle tekst in het dashboard ziet er nu hetzelfde uit, en het is de opmaak van een chat-antwoord geworden: oranje kopjes met een lijntje eronder, oranje pijltjes als opsommingsteken, oranje links, en één soort tabel met een licht-oranje kop en om-en-om een grijze rij. Er bestonden er vier naast elkaar, zonder dat iemand dat besloten had: een tabel in de chat zag er anders uit dan dezelfde tabel in een rapport, en weer anders dan een geplakte tabel; kopjes waren in de chat oranje en elders bruin. Die vier zijn er één geworden, en die geldt voor alles tegelijk: wat het dashboard rendert, wat er in een chat verschijnt, en wat je zelf in een veld typt of plakt. Onder de motorkap besliste ook nog eens elk scherm zelf hoe tekst opgemaakt werd, waardoor in de bespreekpunten, de aantekeningen en de sturing op een taakkaart de opmaaktekens gewoon in beeld kwamen; dat gaat nu allemaal door één poort. Een controle vóór elke bouw leest elke opmaakregel en stopt de bouw zodra er weer een eigen setje bijkomt." },
  { datum: "2026-08-17", tekst: "Wat je zelf in een veld typt of plakt is voortaan net zo mooi opgemaakt als de tekst die het dashboard zelf maakt. Werkte je links in de chat een strategie uit en plakte je die rechts in De koers, dan bleef er een muur tekst over: de kopjes werden gewone letters die aan de volgende zin vastplakten, de opsommingen werden regelafbrekingen, de lijnen verdwenen. Dezelfde tekst een kolom verderop stond wel netjes. Alle vrije tekstvelden (de koers, wat we nu oppakken, de bespreekpunten, de aantekeningen bij een taak) hangen nu aan exact dezelfde opmaak als gerenderde tekst: dezelfde oranje kopjes, dezelfde witruimte, dezelfde bullets, lijnen en tabellen. Bij plakken gaat alleen weg wat van buiten komt, dus lettertype, kleuren en achtergronden uit Sheets, Docs of een webpagina; de structuur van je tekst blijft staan, inclusief koppen, opsommingen, genummerde lijsten, lijnen, citaten, alinea's, tabellen en klikbare links. Plak je platte tekst waar nog opmaaktekens in staan, dan wordt die meteen gerenderd in plaats van letterlijk getoond. Een controle vóór elke bouw haalt een echt stuk strategie door de opschoner heen en stopt de bouw zodra een kop, een bullet, een lijn, een link of een tabel sneuvelt." },
  { datum: "2026-08-17", tekst: "Een mailvenster vult nooit meer zelf een ontvanger in. Er zat een gedeeld geheugen in de browser met het laatst gebruikte adres van de sitebouwer, en dat gold voor alle klanten tegelijk in plaats van per klant. Wie na een mail over de ene klant een mailvenster van een andere klant opende, begon dus met het adres uit de vorige mail, en zo stond bij Kamsteeg Tuinen het adres van Paul Hoevenaars al klaar terwijl dat elkaars concurrenten zijn. Dat geheugen is nu overal weg (vijf schermen), en elk adresveld begint leeg, ook voor het adres van de klant zelf en ook op de developerpagina; er is met opzet geen uitzondering voor adressen die veilig lijken, want zodra er een bij mag komt de volgende er ongemerkt bij. Aanvullen gebeurt alleen terwijl je typt, uit je eigen contacten, en een voorstel wordt pas een adres als je hem aanwijst. Dat aanvulveld zat nog niet bij de bespreeklijstjes, daar stond een kaal invulvak; die hebben het nu ook. Een proef rekent bij elke bouw na dat er nergens meer een adres wordt voorgevuld of onthouden." },
  { datum: "2026-08-17", tekst: "De controle die documenten tegenhoudt bij tegenspraak kan niet meer onterecht blijven hangen. Die poort heeft deze maand vier keer een pagina dichtgezet die niets mankeerde, en drie van die keren is dat opgelost door er uitleg bij te schrijven; dat hielp nooit, want de controle kon alleen maar botsingen opschrijven, ook als hij zelf concludeerde dat er geen botsing was. Bij /hovenier/oosterhout/ stond letterlijk dat klopt en dit is geen conflict in de blokkade, en er kwam alsnog geen document. Er staan nu vier harde sloten in plaats van instructies: een pagina die nog niet live staat wordt helemaal niet gecontroleerd (een plan voor een nieuw te bouwen pagina kan niet botsen met de constatering dat hij er nog niet is), een botsing telt alleen als hij expliciet als hard is aangemerkt, een botsing die zichzelf tegenspreekt gaat weg, en een botsing die een verhaal is in plaats van een feit ook. En er staat voortaan een knop Toch genereren bij de melding: die slaat de controle één keer over en pakt precies de stappen op die niet gemaakt zijn, waarna de volgende run gewoon weer controleert. Zo'n document schrijft nu ook eerlijk dat de pagina nieuw gebouwd wordt in plaats van te doen alsof er bestaande tekst is." },
  { datum: "2026-08-17", tekst: "Wat we nu oppakken kan niet meer stilletjes verouderen. Dat veld verandert alleen als je er zelf in typt, en daardoor stond bij Kamsteeg nog de oude opzet terwijl de strategie een dag eerder in een gesprek volledig herzien was; die verouderde tekst ging bovendien bij elke vraag aan de assistent mee als dit pakken we nu op. Op de kop van het lijstje staat nu de datum waarop het voor het laatst veranderde, en is er daarna nog iets vastgelegd (een gesprek over die klant, of het strategiestuk in het dossier), dan meldt het lijstje dat zelf met naam en datum erbij. De knop Bijwerken maakt daar een voorstel van, met (loopt) achter alles wat al op de planning staat. Dat voorstel staat boven je eigen tekst, dus je ziet oud en nieuw naast elkaar en kiest zelf: Overnemen of Laten staan. Zonder die klik verandert er niets, en na het overnemen staat de vorige versie gewoon in de versiehistorie." },
  { datum: "2026-08-17", tekst: "Twee dingen van vandaag zijn er weer uit: de knop Dupliceren op een taakkaart en de vaste lijst AI-werk in de agenda. Allebei waren ze voor Lifemax bedoeld en niet voor dit dashboard. De regel hieronder van vandaag noemt ze nog; die blijft staan, want dit lijstje is een logboek en geen samenvatting. Wat wel blijft is dat het blok Waar we naartoe werken dichtgeklapt begint." },
  { datum: "2026-08-17", tekst: "Drie kleine dingen. Het blok Waar we naartoe werken begint nu dicht in plaats van open, want opengeklapt duwde het de planning en de chats van het scherm af; klap je een strook open, dan onthoudt hij dat per klant. Een taakkaart heeft een knop Dupliceren zodra je hem openklapt: de kopie krijgt (kopie) achter de titel en staat er direct onder, met dezelfde achtergrond, fases en dag, maar zonder de status, de doorzet-naar-dev en het archief van het origineel. En in de agenda staat AI-werk voortaan altijd tussen de suggesties bij Lijst, voor zowel een tijdblok als een dagtaak, zodat je hem niet elke week opnieuw intypt en er niet per ongeluk twee categorieen ontstaan." },
  { datum: "2026-08-17", tekst: "Claude kan het dashboard nu ook zien in plaats van alleen lezen. Een browser vanuit de Claude-omgeving komt niet bij dit domein (de tunnel komt er wel, maar de verbinding wordt daarna verbroken, terwijl curl over precies dezelfde tunnel gewoon werkt), en dat is van binnenuit niet te repareren. Het is nu van de andere kant opgelost: de server draait zelf al een browser voor de schermafbeeldingen op de uitlegpagina, en die kan zichzelf prima bereiken. Met /api/admin/kijkbeeld?pad=... maakt hij op afroep een foto van elk scherm en geeft die terug. Alleen met adminsessie, en alleen van een pad op dit eigen domein, zodat het geen middel wordt om vanaf deze server een willekeurige andere site op te halen." },
  { datum: "2026-08-17", tekst: "De planning is één lijst geworden. Alles staat onder elkaar op datum: de eerstvolgende bovenaan, wat over de datum heen is met een rood streepje erboven, en wat nog geen datum heeft onderaan. De zeven vakken (Te laat, Vandaag, Morgen, Verder deze week, Volgende week, Later, Nog geen dag) en de kaarten per week zijn allebei weg; die stonden naast elkaar met dezelfde taken erin, dus elke taak stond twee keer op hetzelfde scherm en je scrolde langs zes koppen voor je bij het werk was. Slepen betekent nog steeds precies één ding: laat je een taak op een andere taak los, dan neemt hij diens datum over; laat je hem onderaan los, dan raakt hij zijn dag kwijt. Op de navigatiepagina hebben de menupagina's zelf (Tuinontwerp, Tuinaanleg, Over Ons) nu ook hun eigen regel met woorden, score en voortgang, en de knop + planning loopt niet meer dwars door het percentage ernaast." },
  { datum: "2026-08-17", tekst: "De takenpagina begint nu met waar we naartoe werken. Bovenaan staat een blok met drie stroken: de koers in je eigen woorden (met een knop die alleen commentaar geeft en nooit in je tekst schrijft), wat we nu oppakken (met per regel één klik om er een kaart van te maken op de planning), en een rij doorklikjes naar de prioriteitenscan, Meta & CTR, Opruimen, Interne links en de navigatie-roadmap met het aantal dat er ligt. Die tellingen lezen alleen wat al is opgeslagen, dus openen kost niets; draaide een motor nog nooit, dan staat er nog niet gedraaid en geen 0. Twee dingen die er al waren maar nergens op het scherm stonden, zijn hiermee terug: het veld Top Prio's (dat elke chatvraag al voedde) en de vastgelegde strategiegesprekken met hun actiepunten. Het doodlopende kaartje Zoekwoorden en links staan bij Klantgegevens is weg; die weg staat nu tussen de andere doorklikjes, met de juiste naam Dossier." },
  { datum: "2026-08-16", tekst: "Fundament en Onboarding zijn samengevoegd tot één scherm. Ze rekenden allebei met dezelfde bron en toonden dezelfde cijfers, alleen liet het Fundament op het dossier twee van de vier blokken zien en het tabblad Onboarding alle vier plus de voortgangsbalk. Twee antwoorden op dezelfde vraag betekent dat je altijd de verkeerde openhebt. Bovenaan het dossier staat nu hoe ver deze klant is, met de knop die aanvult wat zonder jou kan en het verslag van de laatste rit, en daaronder alle stappen als tegels in vier blokken: aansluiten, wie is de klant, meten en aan het werk. Het tabblad Onboarding is daarmee vervallen; oude links en bookmarks komen gewoon op het dossier uit." },
  { datum: "2026-08-16", tekst: "Klantgegevens is gesplitst. De tab heet nu Dossier en bevat alleen nog wat je over de klant weet: het fundament, het profiel met de tone of voice, de afgesproken zoekwoorden en links, de bedrijfsgegevens, de kennisbank en de concurrenten. Wat de klant zelf ziet na inloggen stond daar onderaan verstopt onder de concurrenten, en dat is iets heel anders: dat is geen dossierkennis maar het scherm dat je deelt. Dat heeft nu een eigen plek, Klantweergave, in de menugroep 'wat hebben we geleverd', samen met de documenten en Wat we doen. Oude links en bookmarks naar Klantgegevens komen gewoon op het dossier uit." },
  { datum: "2026-08-16", tekst: "De kennisbank is een eigen blok geworden op Klantgegevens, met een eigen kop en een eigen uitleg. Hij stond zonder titel onderin het paneel Bedrijfsgegevens, en zijn twee knoppen ('Materiaal toevoegen' en 'Ontdubbelen') stonden via een omweg tussen de knoppen van dát blok. Je kon dus niet zien dát er een kennisbank was, en de knoppen leken bij iets anders te horen. Hij blijft wel bij de bedrijfsgegevens staan en verhuist niet naar een eigen tabblad: dat zijn twee helften van hetzelfde, want hier gaat materiaal in (documenten, gegevens over vestigingen, schema-code) en daar komen de gecontroleerde gegevens uit die de structured data vullen. Ze uit elkaar halen zou betekenen dat je op twee plekken moet kijken om te zien of iets verwerkt is." },
  { datum: "2026-08-16", tekst: "Het klantprofiel en de zoekwoord- en linkstrategie staan nu waar je ze zoekt: bij Klantgegevens. Het klantprofiel met de tone of voice stond boven de paginalijst van 65 URL's, terwijl de tab Klantgegevens in zijn eigen omschrijving al beloofde dat het daar stond. En 'Zoekwoorden & links' stond bij Taken, terwijl dat een afspraak is die maanden meegaat en geen taak van deze week. Op Taken staat nu de verwijzing ernaartoe in plaats van het veld zelf, dus er is geen tweede kopie die na een maand iets anders zegt. De volgorde op Klantgegevens loopt van wie het bedrijf is, naar wat we afspraken, naar de harde gegevens en de concurrenten. De site-brede strategie-sessies blijven bij Taken, want daar maak je met één klik een taak van een actiepunt. Een proef bewaakt dat het profiel niet terugsluipt naar de paginalijst." },
  { datum: "2026-08-16", tekst: "De navigatie van een klant is één mega menu geworden. Waar je eerst twaalf schermen achter zes knopjes had, met twee uitklapmenu's die een kaal lijstje toonden, klik je nu op 'Alles over deze klant' en zie je alles in één keer, verdeeld over vijf kolommen: wat moet ik nu doen, hoe staat de site ervoor, waar zit winst te halen, wie is deze klant, en wat hebben we geleverd. Bij elk scherm staat de regel uitleg er zichtbaar bij; die bestond al, maar was alleen te zien als je precies lang genoeg stil bleef hangen met je muis. De groepen zijn geen categorieën maar vragen, want dan lees je meteen waaróm een scherm daar staat. Taken en Pagina's blijven ook los in de balk staan (daar ga je tien keer per dag heen) en Developer blijft er los achter, want dat scherm gaat over al je klanten tegelijk. Een proef bewaakt dat elk scherm in precies één groep staat, zodat er nooit eentje buiten het menu valt." },
  { datum: "2026-08-16", tekst: "Losse lange streepjes zijn weg uit het dashboard. De vaste Pingwin-schrijfregel is dat een em-dash of en-dash nooit een zinsscheiding is, maar de assistent hield zich daar niet aan: een vastgelegde strategie kwam voorbij als \"SEO-STRATEGIE KAMSTEEG - VASTGELEGD IN GESPREK\" en \"Laag 1 - Dienstpagina's\". Zo'n streepje wordt nu automatisch een komma, en aan het begin van een regel een gewone bullet. Dat gebeurt in de weergave, dus ook in alles wat er al staat: kaarten, klantprofielen en chat-teksten van eerder zijn er meteen vanaf, zonder dat er iets herschreven hoeft te worden. Een koppelteken in een samenstelling (SEO-strategie, e-mail) en de vaste vorm van een meta-title (\"Onderwerp - Merknaam\") blijven ongemoeid. De instructie aan het model noemt de regel nu ook, dus het opschonen is het vangnet en niet de bedoeling." },
  { datum: "2026-08-16", tekst: "Een lange kaart uit de chat werd stilzwijgend halverwege afgekapt. De assistent liep tegen zijn lengtegrens aan terwijl hij de kaart schreef, stopte middenin een zin, en die halve tekst werd daarna gewoon uitgevoerd en opgeslagen. Zo kwam bij Kamsteeg een SEO-strategie in het klantprofiel te staan die ophield bij \"aanleg en onder\", zonder de prompt voor de plaatspagina's. Er ging technisch niets mis en er was dus ook geen melding; de kaart zag er compleet uit. Vanaf nu wordt zo'n afgekapt antwoord opnieuw gevraagd met ruim drie keer zoveel ruimte, en past het dan nog niet, dan wordt de kaart NIET uitgevoerd maar compacter opnieuw geschreven. De overzichts-chat heeft daarnaast standaard veel meer ruimte gekregen, zodat een volledige strategie of klantprofiel-aanvulling er in één keer in past." },
  { datum: "2026-08-16", tekst: "Twee blokken op de projectkaart die zichzelf altijd vulden, ook als er niets te melden was. \"Waarom deze pagina\" kreeg gegarandeerd een paar zinnen mee bij het aanmaken (\"nog geen Search Console-data\", \"nog geen vastgelegde strategie\", plus de opdrachtregel waarmee de kaart is gemaakt en het aantal fases dat af was). Dat zijn geen redenen, dat is de afwezigheid van een reden, en het aantal fases staat live in het fase-blok eronder. Die regels zijn er nu uit, ook op alle kaarten die er al staan: is er een echte reden (een kans, een positie, cijfers, een afspraak), dan staat die er nog gewoon; is die er niet, dan is er ook geen blok. En de documentenlijst staat voortaan onder een dichte uitklapper \"Documenten (n)\", want de analyse, blauwdruk en copy bereik je al via de fase-rijen. Hij gaat vanzelf open als er meerdere versies van hetzelfde soort liggen en je nog niet hebt aangewezen welke geldt; dan staat het tijdstip er ook bij, want drie keer \"copy (gegenereerd)\" van dezelfde dag kon je niet uit elkaar houden." },
  { datum: "2026-08-16", tekst: "Het zoekwoorden- en linkslijstje werkt weer zoals je verwacht. Het grijpvlekje om iets te verslepen staat nu in een eigen strook links van het tekstvak in plaats van dwars over het nummertje van een genummerde regel. Enter op een vinkregel doet wat het bij elk lijstje doet: aan het eind een nieuw punt, middenin splitst hij de regel (de tekst achter je cursor gaat mee), op een lege regel stap je uit de lijst. Backspace vooraan haalt alleen het vinkje weg en laat je tekst staan. Een uitklapper of vinklijst invoegen terwijl je cursor in een lijst of in een kopje staat knipt die regel niet meer doormidden. En het belangrijkste: na élke bewerking wordt de vorm nagelopen en zo nodig rechtgezet, waarbij nooit iets weggegooid mag worden; wat op een verkeerde plek staat verhuist. Oude, scheefgeraakte velden herstellen daardoor vanzelf zodra je ze opent. Ook het bewaren is dichtgetimmerd: wissel je binnen een seconde van tabblad, dan is wat je net typte niet meer weg." },
  { datum: "2026-08-16", tekst: "Het losse mail-dossierblok (\"Waar deze pagina staat\", met \"Mail erbij zoeken\" en \"Ververs\") is van de projectkaarten in de weekplanning gehaald. De link naar de pagina en naar analyse, blauwdruk en copy stonden al bij de fases eronder, en het matchen van mails erbij werkte niet lekker; eigen punten om te onthouden zet je nu gewoon in de aantekeningen. Op de kaart zie je daardoor voortaan altijd meteen de geschreven tekst (\"Waarom deze pagina\" en \"Aanpak en afspraken\") in plaats van soms een leeg mailblok." },
  { datum: "2026-08-15", tekst: "Tussen je klik op \"nu draaien\" en het moment dat de ronde zich meldt zit ongeveer een minuut, en in die minuut zei het scherm \"er wordt nu niets gebouwd\". Precies op het moment dat je wilt weten of je klik is aangekomen. Er staat nu \"aan het opstarten\" met een lopende balk, de seconden erbij en de mededeling dat je niet nog een keer hoeft te drukken; zodra hij zich meldt schuift de echte stap met tijdsverwachting ervoor in de plaats. Het scherm kijkt tijdens dat opstarten elke vijf seconden in plaats van elke twee minuten, en duurt het te lang, dan zegt hij dat ook." },
  { datum: "2026-08-15", tekst: "De prognose kent nu je echte kostenstructuur, met regels die zichzelf toepassen in plaats van bedragen die je per klant moet bijhouden. MMC-klanten krijgen automatisch 70% van hun eigen maandbedrag als kosten (verhoog je het tarief, dan beweegt dat mee), de maandfactuur van de linkbuilder wordt over je eigen SEO-klanten verdeeld naar rato van hun linkbuildingbudget, en hosting (Greenbug) en Google Ads (Gladior) gaan als vaste maandpost van het totaal af omdat die omzet niet per klant in het dashboard staat. Eén knop haalt alle leveranciersbedragen tegelijk op uit Moneybird; verder valt er niets aan te vinken. Een klant die onder een regel valt gebruikt die regel en niet ook nog zijn eigen linkbuildingbedrag, dus er wordt nergens dubbel geteld." },
  { datum: "2026-08-15", tekst: "Het Intern-menu is opgeschoond: de vijftien schermen staan nu in drie groepen (dagelijks werk, ontwikkeling van het dashboard, beheer en controle) in plaats van in \u00e9\u00e9n lange lijst, en de dubbele ingangen zijn eruit. De routekaart stond er twee keer in en er liepen drie losse links naar dezelfde uitlegpagina; dat zijn nu \u00e9\u00e9n en \u00e9\u00e9n. En elke ronde zegt voortaan in zijn logboek welke rekening het denkwerk betaalt, je abonnement of de betaalde sleutel, zodat je dat nooit meer hoeft uit te zoeken." },
  { datum: "2026-08-15", tekst: "De linkbuilder kies je nu uit een lijst van je Moneybird-contacten in plaats van dat er op een mailadres gezocht wordt. Dat zocht namelijk mis: de linkbuilding komt van info@co.vision, maar in de boekhouding staat die leverancier onder zijn bedrijfsnaam, en dan vond hij niets zonder te zeggen waarom. En omdat op die facturen geen klantnaam staat (ze heten \"Linkbuilding februari 2026\"), valt de linkbuilding niet per klant toe te wijzen. Dat bedrag verdwijnt nu niet meer uit beeld: je ziet het maandbedrag met de facturen erachter, en met één knop telt het als vaste maandpost mee in de prognose. Verdelen over de klanten die toevallig wel herkend worden gebeurt bewust niet, want dan wordt de marge per klant een schatting die niemand later nog als schatting herkent." },
  { datum: "2026-08-15", tekst: "De Claude-gebruiksaanwijzing op /admin/claude-werkwijze is nu een levende lijst in plaats van een vast lapje tekst: zes hoofdstukken met een snelmenu bovenaan, per tip het scherm waar het over gaat (klikbaar) en de dag waarop we het geleerd hebben. Zeg tegen Claude \"zet dit er ook bij\" en er komt \u00e9\u00e9n blok bij, in het hoofdstuk waar het thuishoort; twee chats op dezelfde dag botsen daardoor niet meer. Er staan meteen de lessen van vandaag in: waarom een chat niets extra kost en een ronde in het dashboard wel, hoe je dat omzet, en waarom je er altijd bij moet zeggen in welk scherm iets staat." },
  { datum: "2026-08-15", tekst: "De prognose vult zichzelf nu vanuit Moneybird: één knop haalt op wat elke klant de laatste zes afgesloten maanden werkelijk factureerde, en haalt de linkbuilding uit de factuurregels van je linkbuilder (instelbaar, standaard info@co.vision). Maandklanten en kwartaalklanten worden uit elkaar gehouden, een eenmalige projectfactuur tilt het maandbedrag niet op, en linkbuilding die bij geen enkele klant te plaatsen is wordt niet uitgesmeerd maar apart getoond. Je krijgt eerst een voorstel te zien (wat staat er nu, wat zegt de boekhouding, en waarom) en vinkt zelf aan wat je overneemt. Bedrijven die wel factureren maar niet in het dashboard staan komen er apart bij, want dat is omzet die nu buiten de prognose valt." },
  { datum: "2026-08-15", tekst: "Financiën heeft er een prognose bij: wat gaat er de komende maanden verdiend worden. Lopende klanten tellen vol mee, leads naar de kans dat ze doorgaan (inclusief hun kosten, dus een koude lead trekt de lijn nooit omlaag), en daar gaan je eigen vaste lasten één keer per maand af. Klik een maand open en je ziet precies uit welke klanten, leads en losse posten het bedrag is opgebouwd. Bovenaan staat waar je nu staat, wat het doel is, hoeveel er nog te gaan is (ook in klanten uitgedrukt) en in welke maand het doel gehaald wordt. Het maandbedrag en de linkbuilding bewerk je hier rechtstreeks; ze blijven dezelfde cijfers als in de cockpit van die klant. Vaste lasten kun je laten vullen met het gemiddelde uit de boekhouding." },
  { datum: "2026-08-15", tekst: "De nachtelijke rondes kunnen nu op je Claude-abonnement draaien in plaats van op een aparte rekening per verwerkt woord. Dat is het verschil tussen 7 dollar voor \u00e9\u00e9n plan en niets extra, want in een gewone chat betaal je die woorden ook niet apart. Zodra je CLAUDE_CODE_OAUTH_TOKEN als repo-secret in GitHub zet, schakelen beide rondes vanzelf over; staat hij er niet, dan blijft de oude sleutel werken en verandert er niets." },
  { datum: "2026-08-15", tekst: "Een plan schrijven ging altijd op het zwaarste model, ook voor een simpele vraag: dat kostte bij G1 veertien minuten en 7,24 dollar, en er kwam niets uit. Klein en middel gaan nu op het snelle model, alleen een groot punt krijgt het zware. Verder neemt een punt dat uit een tweak ontstaat nu het scherm en de schermafbeelding mee (die werden weggegooid, waardoor de ronde zelf moest raden waar je het over had), staat er bij een punt welk scherm het raakt met een knop om het beeld te bekijken, en laat een vastgelopen ronde voortaan een regel in het draadje achter in plaats van te doen alsof er nooit iets gebeurd is. De tijdsverwachting van een plan wordt nu gemeten in plaats van vast op twintig minuten te staan." },
  { datum: "2026-08-15", tekst: "De kijk-sleutel voor Claude vervalt niet meer vanzelf. Een nieuwe maken trok tot nu toe de oude in, en de foutmelding raadde precies dat aan; daardoor kon je de hele dag blijven plakken zonder dat het ooit goed kwam. Nu blijft elke sleutel geldig tot je hem zelf intrekt, opent elke geldige sleutel de deur, en zijn de sleutels van deze week teruggezet zodat wat er al in een Claude-omgeving staat weer werkt. Op de knop drukken kan geen kwaad meer." },
  { datum: "2026-08-15", tekst: "\"Begin nu met het plan\" deed nog steeds niets: de nachtronde startte wel, maar las bij het dashboard het verkeerde woord (wat er nú loopt in plaats van wat er klaarstaat) en sloeg daardoor zowel bouwen als plannen over, met een groen vinkje erbij. Ook het nachtelijke bouwen liep hierdoor leeg. De ronde leest dat nu op zijn eigen plek, mislukt zichtbaar bij een antwoord dat hij niet kent, en een proef rekent het bij elke bouw na. De knop zelf meldt pas succes als er echt iets gestart is en gaat tijdens het starten op slot, zodat één twijfelklik geen vier rondes meer in de rij zet." },
  { datum: "2026-08-15", tekst: "De verwachte tijd van een ronde wordt niet meer geschat maar gemeten: het dashboard onthoudt van elke afgeronde ronde hoe lang hij duurde en hoeveel er in zat, en rekent daaruit twee getallen uit (de vaste kosten per ronde en de tijd per aanpassing). Na drie rondes staan je eigen cijfers op het scherm in plaats van een startwaarde, en het scherm zegt erbij waar het op rust. Wordt bouwen sneller of trager, dan beweegt de verwachting vanzelf mee." },
  { datum: "2026-08-15", tekst: "De voortgangsbalk van een tweak-ronde stond de hele ronde op '0 van 3' en sprong dan ineens naar 3, omdat meldingen pas na het live zetten werden afgevinkt. Nu meldt de ronde elke aanpassing zodra hij hem geschreven heeft, dus de balk loopt tijdens het werk mee, met de fase erbij (aan het bouwen, dan proeven en live zetten). En de resterende tijd telt echt af in plaats van op hetzelfde getal te blijven staan." },
  { datum: "2026-08-15", tekst: "De tijdsverwachting van een tweak-ronde klopt nu met de werkelijkheid: gemeten rondes duurden drie tot zes minuten, terwijl het scherm er achttien voorspelde. Je ziet nu per aanpassing wat hij ongeveer kost (± 1,5 minuut) én het totaal, met erbij waar de tijd heen gaat: ongeveer vijf minuten opstarten, proeven en live zetten, en dat is even lang voor één aanpassing als voor tien. Eén ronde met tien tweaks is dus veel goedkoper dan tien losse rondes." },
  { datum: "2026-08-15", tekst: "De regel wanneer een tweak 'te groot' is, is flink versoepeld: een aanpassing die meerdere schermen tegelijk raakt (zoals overal een tooltip) is juist een goede tweak en wordt gewoon gebouwd. Er wordt alleen nog geparkeerd als jij moet kiezen, als er iets van buiten nodig is, of als het niet kan zonder iets te slopen. En wat er toch geparkeerd staat zet je met één knop allemaal tegelijk terug in de wachtrij." },
  { datum: "2026-08-15", tekst: "Meldingen die een ronde te groot vond stonden verstopt achter 'ook de afgeronde'; ze staan nu gewoon in beeld onder 'Te groot gebleken, wat wil je ermee?', want ze wachten op jou en zijn niet klaar. De knop 'Begin nu met het plan' deed niets doordat de ronde zichzelf overdag weigerde; die weigering is weg. In de schermenlijst staat nu '3 meldingen' in plaats van een kaal getal, en het blok dat naar de grote punten verhuisde is van de tweak-pagina af." },
  { datum: "2026-08-15", tekst: "De tweak-stapel en de grote punten zijn opgeschoond: de introductieteksten onder de titels zijn weg, beide schermen linken naar elkaar, en er staat altijd een stand in beeld (loopt er een ronde en hoe ver, of hoeveel er wacht). Een groot punt waar nog niets voor draait zegt nu 'nog niet begonnen' met een knop om het plan meteen te laten schrijven, in plaats van eruit te zien alsof er nagedacht wordt. In de schermenlijst opent elk scherm in een nieuw tabblad, zodat je de lijst niet kwijtraakt." },
  { datum: "2026-08-15", tekst: "Er draait niets meer elk uur. Tweaks start je zelf met de knop, een plan begint zodra je op 'maak er nu een plan van' drukt, en alleen goedgekeurde grote punten worden 's nachts vanzelf gebouwd: één tik aan het begin van de nacht, en daarna geeft elke klare ronde door aan de volgende in plaats van dat er steeds gekeken wordt. Op de tweak-stapel zie je nu ook een echte voortgangsbalk: hoeveel van de meldingen doorgevoerd zijn, hoe lang de ronde bezig is en hoe lang het nog ongeveer duurt. En beide wachtrijen linken naar elkaar." },
  { datum: "2026-08-15", tekst: "Een ronde haalt zijn toegang nu bij het dashboard zelf op in plaats van bij de meekijk-sleutel. Dat moest: die sleutel vervalt zodra je in de cockpit een nieuwe maakt, en daardoor kwam elke tweak-ronde er niet meer in, meldde toch dat hij geslaagd was, en bleven je meldingen gewoon in de wachtrij staan. Een ronde die er niet in komt mislukt nu zichtbaar, het uurwerk van beide wachtrijen draait vanuit het dashboard, het tweak-scherm kijkt zelf elke vijftien seconden of een ronde nog loopt, en bij het schrijven van een plan zie je nu ook een balk met stappen en een tijdsverwachting." },
  { datum: "2026-08-15", tekst: "Grote punten hebben een eigen wachtrij op /admin/grote-punten: eerst samen een plan in het draadje bij het punt, dan jouw akkoord, en daarna wordt er 's nachts één per keer gebouwd. Bovenaan zie je welk punt loopt, bij welke stap hij is en hoe lang het nog duurt; bij elk punt in de rij staat wanneer het aan de beurt is." },
  { datum: "2026-08-15", tekst: "De tweak-stapel is nu een echte wachtrij. De volgorde op het scherm is de volgorde waarin de eerstvolgende ronde ze doet, en die sleep je zelf aan het greepje; per melding kun je \"direct doorvoeren\" (springt vooraan) of \"parkeren\" (blijft staan, gaat nergens in mee tot je hem terugzet). Er kan nog maar één ronde tegelijk lopen: een ronde begint door een slot in de database te pakken, en wie het niet krijgt bouwt niets, want twee rondes tegelijk in dezelfde bestanden is de bekendste manier om werk kwijt te raken. Valt een ronde halverwege dood, dan valt dat slot na drie kwartier vanzelf vrij en staan de meldingen weer gewoon in de rij. Nieuw is ook de knop \"Nu draaien\", die een ronde start zonder dat je een chat opent (daar zijn twee sleutels voor nodig; zolang die er niet zijn zegt de knop precies welke). Een groter idee waar je ja tegen zegt gaat met één knop naar de routekaart, waar hij zichtbaar wacht op een nummer in plaats van te blijven hangen tussen de aanpassingen van twee minuten. En onderaan staat de nulmeting: een afvinklijst van álle schermen (het Intern-menu plus de tabbladen van een klant), zodat je van elk scherm weet of het goed is of alleen ongezien." },
  { datum: "2026-08-15", tekst: "De huisstijl van knoppen wordt vanaf nu nagerekend in plaats van onthouden: een nieuwe controle leest elke knop in het dashboard en houdt de bouw tegen bij een knop die het knopsysteem niet gebruikt of een emoji in het label heeft. Alle emoji zijn meteen uit de knoplabels gehaald (Site gekoppeld, Verwerkt, Mail, Uitgevoerd en nog drie), en op die regel staat geen enkele uitzondering, zodat hij niet langzaam kan uithollen. De 57 bestanden met oudere knoppen staan op een lijst die alleen korter mag worden." },
  { datum: "2026-08-15", tekst: "De tweak-stapel heeft nu een volledige lus. Per melding kies je \"kleine aanpassing\" of \"groter idee\": kleine gaan mee in de eerstvolgende ronde, grote krijgen eerst een voorstel. Elke melding heeft een stand (in de wachtrij, wordt gebouwd, staat live controleer het, klaar), en zodra er iets live staat verschijnt er vanzelf een melding in de kopbalk. Klopt het niet, dan druk je op \"Nog niet goed\", typ je erbij wat er mis is, en gaat dezelfde melding met jouw correctie eronder terug de wachtrij in, dus geen tweede briefje maar één draadje per onderwerp met een teller hoeveel rondes het kostte. En er draait elk uur vanzelf een ronde als er iets klaarstaat." },
  { datum: "2026-08-15", tekst: "Een meegestuurd document staat in \"Mail vanuit deze kaart\" nu als klikbare link met de NAAM van het document erop, in plaats van een Google Docs-adres van honderd tekens. Noemt de tekst die naam al, dan wordt díe naam de link; anders komt er onderaan een regel bij. Wat je in het schrijfvenster ziet is precies wat de ontvanger krijgt, en klikken opent het document zodat je kunt controleren of het de goede tekst is. Het adresveld stelt bovendien namen voor uit je eigen contacten (typ \"ma\" en Maarten wordt voorgesteld, kiezen met de pijltjes of een klik); dat zat alleen in het mailvenster van het Werkzaamheden-tabblad en is nu één veld dat elk mailvenster gebruikt." },
  { datum: "2026-08-15", tekst: "De links die je aanvinkt bij \"Meesturen\" in \"Mail vanuit deze kaart\" (de pagina, de copy, de blauwdruk) staan nu meteen zichtbaar onderaan de mail, met het volledige webadres erbij, zodat je ze in een zin kunt verwerken in plaats van dat ze pas bij het versturen onzichtbaar werden aangeplakt. Zet je zo'n adres zelf in een zin, dan blijft het daar staan en komt het er niet dubbel onder. De ontvanger krijgt nog steeds netjes de naam van het document als link, geen adres van honderd tekens. Verder zweven \"Mail vanuit deze kaart\" en \"Zet klaar voor de sitebouwer\" nu allebei midden op het scherm met ruimte eromheen, in plaats van dat ze met de bovenkant onder de kopbalk bleven hangen; past de inhoud niet, dan scrolt het venster vanbinnen en blijft de kop met het kruisje staan." },
  { datum: "2026-08-15", tekst: "Nieuw: het knopje \"Tweak\" rechtsonder op elk beheerscherm. Zie je tijdens het werken iets kleins dat anders moet, dan meld je het daar meteen, in je eigen woorden, met een schermafbeelding erbij als je wilt; het scherm, het pad en de klant gaan automatisch mee. Alle meldingen komen op /admin/tweaks te staan met een teller, en één knop zet de startregel klaar waarmee de hele stapel in één ronde wordt doorgevoerd: één keer inlezen, één bouw, één keer live. Dat is er de hele bedoeling van, want de tijd van zo'n kleine aanpassing zat niet in het bouwen maar in de aanloop en de deploy eromheen, en die betaal je per ronde in plaats van per aanpassing." },
  { datum: "2026-08-14", tekst: "Meesturen-lijstjes (in het doorzet-venster naar de developer en in de mailvensters) toonden bij de copy soms twee regels die er identiek uitzagen: \"Copy\" en \"Copy-doc\", zonder dat te zien was of dat hetzelfde bestand was of niet. Elke regel toont nu de echte bestandsnaam (\"Copy: Copy-briefing-hovenier-uden\") in plaats van het kale woord \"Copy\"; is het toevallig hetzelfde bestand, dan komt het er nog maar één keer in te staan." },
  { datum: "2026-08-14", tekst: "\"Mail vanuit deze kaart\" (de knop Mail op een projectkaart) kan nu ook screenshots meesturen: plakken of slepen in het tekstvak werkt hier voortaan net als in de andere mailvensters. Ze gaan verkleind (max 1400px) onderaan de mail mee, met een voorbeeld en een kruisje om er eentje weer weg te halen (max 6)." },
  { datum: "2026-08-14", tekst: "De interne documentweergave (waar een link naartoe wijst als een stap ooit zonder gekozen Drive-map is gemaakt) heeft nu de knop \"Kies Drive-map en upload\": hij zet de al vastgelegde tekst om naar het Pingwin-document in de gekozen map, zonder de tekst opnieuw te laten schrijven. Vanaf dat moment gebruiken Developer en Mail die nieuwe Drive-link vanzelf, in plaats van dat je de hele stap opnieuw moet starten." },
  { datum: "2026-08-14", tekst: "Het openen van een projectkaart met een gevuld maildossier gaf een zichtbare flits: \"Waarom deze pagina\" en \"Aanpak en afspraken\" verschenen even en werden dan meteen weer weggehaald zodra bleek dat het levende dossier hetzelfde verhaal actueler vertelde. Die twee blokken tonen zich nu pas zodra vaststaat dat ze nodig zijn, dus nooit meer aan en meteen weer uit." },
  { datum: "2026-08-14", tekst: "Een Drive-map kiezen is nu verplicht vóór elk document, in plaats van een vrijblijvende suggestie. Start je op de projectkaart een fase die een document maakt (strategie vastleggen, analyse, blauwdruk, copy, \"Alles in één keer\") zonder gekozen map, dan klapt de mapkiezer vanzelf open en draait de actie pas zodra je kiest of een nieuwe map maakt. Hetzelfde geldt nu op de Pagina's-pagina voor \"Vat samen & leg strategie vast\", \"Document opnieuw maken\", en het overnemen van interne links, structured data en cannibalisatie-aanbevelingen. Zo landen alle documenten van een pagina, in elke fase, gegarandeerd in dezelfde klantmap in Drive, in plaats van dat een deel daar terechtkomt en een ander deel alleen in het dashboard blijft hangen." },
  { datum: "2026-08-14", tekst: "Vervolgreparatie: het copy-document ontbrak nog steeds in het mail- en doorzetvenster als de copy ooit zónder gekozen Drive-map was gemaakt (er lag dan geen Drive-link, dus was er niets om aan te vinken, ook al bestond de tekst wel). Ontbreekt die Drive-link, dan wijst het venster nu naar de interne documentweergave (met daarin de knop om alsnog een Word-bestand te downloaden), voor copy, blauwdruk én analyse. Zo staat er altijd iets om mee te sturen zodra een stap gegenereerd is." },
  { datum: "2026-08-14", tekst: "Drie reparaties rond het doorzetten naar de developer. Eén: het copy-document werd wel getoond in het doorzet-venster en het mailvenster, maar stond niet standaard aangevinkt, waardoor een taak of mail er soms zonder de copy uitging; hij staat nu standaard aan (naast de pagina en een eventuele goedgekeurde klantversie). Twee: bij een pagina met meerdere losse klantversies kon de copy zelfs helemaal buiten de lijst vallen door de grens van zes documenten; copy, blauwdruk en analyse staan nu vooraan in de lijst en vallen dus nooit meer weg. Drie: de \"Gedaan\"-meting (en \"Is dit doorgevoerd?\") toont nu een klikbare link naar het document waarmee vergeleken is, zodat duidelijk is welke copy-versie de bron was." },
  { datum: "2026-08-14", tekst: "De Implementatie-rij op een projectkaart heeft nu ook \"Developer\" (hetzelfde doorzet-venster als onderaan de kaart, met de Drive-documenten erbij) en \"Gedaan\" (her-fetcht de live pagina en meet of de wijziging er echt staat; klopt het, dan vinkt Implementatie zichzelf af en kun je door naar Structured data), naast de bestaande Mail-knop. En start je een analyse, blauwdruk of copy zonder dat er een Drive-map gekozen is, dan knippert de knop \"Drive-map kiezen of maken\" nu even en klapt de mapkiezer meteen open, zodat het geen document meer wordt dat stilletjes zonder klantmap blijft staan." },
  { datum: "2026-08-14", tekst: "Het aparte vak \"Opdrachten in deze kaart\" op een projectkaart is weg: de herkomst van zo'n regel (chat, mail, scan, of eigen tekst) was er niet aan af te zien, dus ook niet te vertrouwen als los, afvinkbaar lijstje. De tekst zelf is niet weg; die staat nu gewoon onder \"Aanpak en afspraken\", net als de rest van de kaart." },
  { datum: "2026-08-14", tekst: "Advies dat je met \"Gelieerde pagina's\" naar andere pagina's doorgeeft, wordt nu automatisch overal ingetrokken zodra je de strategie van de bronpagina opnieuw vastlegt; oud advies kan de nieuwe strategie dan niet meer tegenspreken. Op de ontvangende pagina zie je dat meegegeven advies nu ook met een knop \"Negeer dit advies\" als het achterhaald is, en de chat weegt jouw eigen, actuele tekst voortaan altijd zwaarder dan zo'n ouder advies." },
  { datum: "2026-08-14", tekst: "Het Developer-tabblad is opgeruimd: de pagina staat weer binnen de normale schermbreedte in plaats van beeldvullend, de kolom \"Opm. developer\" en de knop \"Kaart\" (voor de developer niet relevant) zijn weg uit de lijst per klant, en een taak met een lange titel blijft nu één regel hoog met puntjes erachter in plaats van de hele rij op te rekken." },
  { datum: "2026-08-14", tekst: "In het Developer-tabblad kun je nu bij een taak die van een projectkaart komt met één klik \"Is dit doorgevoerd?\" checken, zonder eerst de kaart in de weekplanning op te hoeven zoeken. En in elk mailvenster in het dashboard (zoals \"Mail over deze taak\") kun je nu een screenshot plakken of erin slepen; hij gaat als afbeelding onderaan de mail mee." },
  { datum: "2026-08-14", tekst: "\"Wat we doen\" is compleet gemaakt: een taak die je op Klaar/Verwerkt zet komt er nu vanzelf in, net als een verstuurde mail met echt werk erin (met klikbare link naar de mail, standaard alleen voor jou zichtbaar totdat je 'm deelt) en een gedetecteerde sitewijziging (nu met de echte oude en nieuwe tekst in plaats van \"pagina aangepast\"). Bestaande regels zoals een redirect tonen voortaan het echte van-adres en naar-adres in plaats van een vaste zin. Heeft een dag meer dan vijf regels van hetzelfde type (bijvoorbeeld tientallen redirects), dan vouwt die groep zich automatisch samen tot één regel die je open kunt klikken." },
  { datum: "2026-08-13", tekst: "\"Mail erbij zoeken\" op een kaart doorzocht alleen de laatste vijftien mails van de klant, in willekeurige volgorde qua onderwerp; de mail die echt bij de pagina hoorde stond er daardoor vaak niet eens bij. Hij zoekt nu ook gericht op de kernwoorden van de pagina, net als de automatische koppeling, sorteert op relevantie, en laat automatische meldingen (Ahrefs, Search Console e.d.) helemaal weg; dat is geen correspondentie over een pagina." },
  { datum: "2026-08-13", tekst: "Twee reparaties aan de mailkoppeling per pagina, naar aanleiding van een kaart die een mail over iets heel anders (een concurrerende kliniek) als \"bewijs\" liet zien. Eén: de AI-controle die per mail beoordeelt of hij echt bij de pagina hoort, gaf de mails eerder lange, op elkaar lijkende mail-kenmerken mee; bij een lange lijst kon het model daardoor het oordeel van de ene mail aan een andere vastplakken. Nu krijgt elke mail een simpel volgnummer, dat is voor een taalmodel veel lastiger te verwisselen. Twee: \"Mail erbij zoeken\" op een kaart toonde altijd gewoon de laatste vijftien mails van de klant, in willekeurige volgorde qua onderwerp; die lijst staat nu gesorteerd op wat er echt bij de open pagina past, met dezelfde puntentelling die de automatische koppeling ook gebruikt." },
  { datum: "2026-08-12", tekst: "De documentketen heeft nu een poort tegen tegenspraak: vlak voor een analyse, blauwdruk of copy gegenereerd wordt, vergelijkt het dashboard het vastgelegde plan en de eerdere stappen met de verse meting van de pagina. Botst een claim hard met een gemeten feit (het plan noemt een sectie \"ontbrekend\" die live al bestaat, of verwijst naar een pagina die niet bestaat), dan komt er geen document maar een melding die precies zegt welke claim botst met welk feit en hoe je verder kunt. Daarbij hoort de werkregel dat een strategie intern blijft totdat de analyse hem bevestigd heeft; de assistent wijst je erop als je een onbevestigde strategie naar een klant wilt sturen. Liever geen document dan twee documenten die elkaar tegenspreken." },
  { datum: "2026-08-12", tekst: "Drie adviesregels aangescherpt, geboren uit een echte klantcasus waarin de sitebouwer de pagina net zelf had bijgewerkt: (1) bij elk pagina-advies en elk document wordt de pagina op dat moment vers opgehaald, met de datum erbij (\"live gecheckt op ...\"), zodat een advies nooit meer iets kan \"missen\" dat er al op staat; (2) de commerciële laag wordt gedoseerd naar de top 10 in Google (overwegend informatieve zoekresultaten = een kort kostenblok met link, geen volledige verkoopsecties); (3) zoekersvragen worden eigen koppen in de tekst in plaats van een los FAQ-blok, want FAQ-blokjes in de zoekresultaten bestaan sinds mei 2026 niet meer en de waarde zit in het antwoord zelf." },
  { datum: "2026-08-12", tekst: "De sitemap-check kan het nu aan Google zelf vragen: het blok \"Wat ziet Googlebot?\" inspecteert een dwarsdoorsnede van pagina's via Search Console (URL-inspectie) en toont per pagina wanneer Googlebot er voor het laatst was, of het ophalen toen lukte (daar zie je een blokkade) en of de pagina in de index staat. Zo is met feiten te zeggen of een botblokkade op de site ook Google raakt, of alleen meettools." },
  { datum: "2026-08-12", tekst: "Per klant is er nu een sitemap-check (link bij Zoekwoorden & links en bij de paginalijst). Die haalt de sitemap van de site vers op en beantwoordt drie vragen met feiten in plaats van vermoedens: is de sitemap zelf bereikbaar en verwijst robots.txt ernaar, welke live pagina's staan er niet in (met hun vertoningen, belangrijkste bovenaan), en welke regels erin wijzen naar een pagina die al is omgeleid of weg is. Aanleiding: bij One Day Clinic bleek de sitemap niet bij te houden wat er echt live staat, en blokkeerde de site bovendien geautomatiseerde lezers van het bestand. De uitkomst is meteen de werklijst voor de sitebeheerder." },
  { datum: "2026-08-12", tekst: "De paginalijst mist geen live pagina's meer, en besluiten uit een chat landen voortaan op de werklijst. Bij het inlezen van een website worden nu vier bronnen verenigd (sitemap, Search Console, Ahrefs en de interne links op de pagina's zelf) in plaats van alleen de sitemap; een live pagina die niet in de sitemap staat krijgt het label \"niet in sitemap\", want dat is zelf een bevinding. Aanleiding: een pagina van One Day Clinic die op ruim twintig zoektermen rankte was voor het dashboard onzichtbaar. Daarnaast kunnen cluster-besluiten uit een chat (zoals de vijf besluiten over het cluster \"soa test amsterdam\") nu rechtstreeks in de werklijst worden opgenomen, met label \"besluit uit chat\" en de volledige onderbouwing; ze overrulen de motor-uitkomst, net als een handmatige correctie. En zodra de laatste samenvoeging naar een doelpagina is doorgevoerd, zet het dashboard automatisch één optimalisatietaak voor die pagina op de weekplanning: eerst alles erin, dan pas optimaliseren, zonder dat iemand dat moment hoeft te bewaken." },
  { datum: "2026-08-12", tekst: "De samenvoegingen in de werklijst hebben nu hun eigen doorvoerknop, en die dwingt de goede volgorde af: eerst de content, dan pas de redirect. Eén klik op \"Wat moet er over?\" vergelijkt de pagina met zijn doel en zegt precies wat het doel nog mist: welke secties, welke zoekopdrachten waarop de oude pagina wordt gevonden, en welke interne links nog naar het oude adres wijzen. Daar rolt een kant-en-klare, genummerde instructie voor de sitebouwer uit, die met \"Naar planning\" op de taakkaart meegaat en los te kopiëren is. De redirect-knop gaat pas open nadat \"content staat over\" is aangevinkt, en die poort zit ook aan de serverkant. Is er niets over te zetten (geen eigen secties, geen zoektermen die het doel niet dekt), dan zegt het briefje dat zelf en kan de redirect meteen. Een pagina die niet gelezen kon worden geeft nooit \"meteen\": bij een meetfout blijft de poort dicht." },
  { datum: "2026-08-12", tekst: "Het chatscherm van de paginakaart (de zes stappen bij een pagina: strategie, doorgeven, documenten, cannibalisatie, interne links en structured data) stond als één bestand van 1.662 regels in de code, het laatste en lastigste te grote bestand. Elke werksessie die iets aan één stap deed moest in dat ene bestand schrijven, dus twee sessies op één dag botsten altijd. Het is nu een bestand per stap, met een karkas dat alleen nog vasthoudt wat stappen samen gebruiken (de Drive-map, de foutregel, de klaar-standen); het grootste stuk is 398 regels. Op het scherm verandert er niets: oud en nieuw zijn met dezelfde gegevens en dezelfde kliks naast elkaar gezet en tekenen letter voor letter dezelfde HTML, in drie situaties (vol scherm, leeg scherm, analyses die draaien). Daarmee is de erfenis-lijst van de 1.000-regels-poort weer een bestand korter." },
  { datum: "2026-08-11", tekst: "De werklijst van het opruimen laat nu zien hoever je bent. De kaarten telden alleen werk (\"38 opruimen\" bleef 38, ook als de eerste omleidingen al live stonden); onder opruimen en samenvoegen staat nu hoeveel er al op de site staan en hoeveel er nog te gaan zijn, met bij de regel zelf een label \"staat op de site\". Dat komt uit dezelfde vastgelegde besluiten waarin de doorvoerknop zijn vinkje zet, dus een redirect die je eerder of via de oude tabel plaatste telt gewoon mee, en \"Voer alles door\" slaat die regels voortaan over in plaats van ze nog een keer te plaatsen. Verder zijn de groepen in de lijst uitklappers geworden die standaard dicht staan: die ene groep van 38 duwde de andere vier besluiten van het scherm af, en dicht zie je in vijf regels waar het werk zit. Filter je op één besluit, dan staat die groep wel open." },
  { datum: "2026-08-11", tekst: "De projectkaart in de weekplanning stond als één bestand van 1.206 regels in de code: de kop, de fases, het gesprek, het dossier, de bespreeklijst en de werklijst door elkaar heen. Elke werksessie die iets aan de kaart deed moest daar in schrijven, dus twee sessies op één dag botsten altijd, ook als de een aan de chat werkte en de ander aan de fases. Het is nu een bestand per onderdeel, met een karkas van 150 regels dat ze alleen nog in de goede volgorde zet; het grootste stuk is 339 regels. Op het scherm verandert er niets, dat is regel voor regel nagelopen. Er is meteen een poort bijgekomen die de bouw tegenhoudt zodra een bestand weer boven de 1.000 regels uitkomt, met de vier bekende dikkerds op een lijst die alleen korter mag worden." },
  { datum: "2026-08-11", tekst: "De uitleg die je nu leest stond als één bestand van 2.629 regels in de code, en elke werksessie die iets opleverde moest daar in schrijven. Twee sessies op één dag botsten dus altijd, in tekst die niets met elkaar te maken had. Het is nu één bestand per hoofdstuk, en de twee grootste hoofdstukken (de motoren en de eerlijke agenda) hebben een eigen map met een bestand per onderwerp: acht motoren apart, en de drie golven van de routekaart apart. Aan de tekst zelf is geen letter veranderd, dat is nagerekend. Een poort bewaakt dat geen enkel stuk terug boven de 250 regels groeit en dat er nooit een hoofdstuk losraakt van de pagina." },
  { datum: "2026-08-11", tekst: "Haalt een paginatitel of omschrijving onze eigen lat niet, dan zegt de oplevering er nu bij waaróm, en of het aan de tekst ligt of aan het opgegeven zoekwoord. Dat laatste bleek bij een echte pagina het geval: het primaire zoekwoord stond er als een zin van vijf woorden, en zoiets kan per definitie niet vooraan in een titel van zestig tekens staan en niet letterlijk in een leesbare omschrijving. Drie criteria zakken dan zonder dat er iets mis is met het schrijfwerk." },
  { datum: "2026-08-11", tekst: "In een copy-briefing stonden de vier stappenblokken zonder titel en zonder nummer in beeld, met een kader dat onderaan te veel lucht overhield. Het bolletje en de titel zaten in een tabelletje bínnen het kader, en niet elke lezer tekent zoiets; de hoogte rekende wél met die titelregel, vandaar de ruimte. De titel staat nu boven het kader, precies zoals een hoofdstuktitel is opgebouwd, en het kader bevat alleen nog de tekst en sluit daar strak omheen. Er staat ook wat vet in, zodat het geen egale blokken meer zijn." },
  { datum: "2026-08-11", tekst: "Bij de paginatitel en de omschrijving staat in het klantdocument nu de verificatie: elk criterium waaraan getoetst is, met de gemeten waarde erachter. Dat is exact dezelfde criterialijst als het meta-paneel in het dashboard gebruikt, inclusief de pixelbreedte, dus het document kan niet iets anders beweren dan het scherm. De lijst verschijnt alleen als álles klopt, want een kruisje in een oplevering is een oordeel over eigen werk." },
  { datum: "2026-08-11", tekst: "Uitgezocht waarom de paginatitel en de omschrijving niet altijd aan de criteria voldeden: we gaven het model een regel in tekens en rekenden het af in pixels, en die twee liepen niet gelijk. Een omschrijving van 129 tekens haalde onze eigen tekenregel en bleef twintig pixels onder het venster van Google. De pixel is nu de enige norm en het tekenbereik wordt daaruit afgeleid, aan de tekst zelf gemeten. Daarbovenop hoort het model hoevéél het scheelt in plaats van alleen dat het mis is, levert het drie varianten per ronde in plaats van één, en is er een laatste slag op puur rekenwerk die inkort op een natuurlijke grens of aanvult met eigen woorden van de klant, en die niets doet als het resultaat niet echt klopt. Haalt een tekst het dan nog niet, dan meldt de oplevering dat in plaats van te zwijgen." },
  { datum: "2026-08-11", tekst: "De copy-briefing zei alles twee keer: het opgeslagen copydocument is zelf al een briefing, en het klantdocument bouwt diezelfde hoofdstukken vers op uit de actuele cijfers. Uit dat opgeslagen document komen nu alleen nog de webteksten, waardoor ook de aanduidingen H1, H2 en H3 weer alleen bij tekst staan die echt op de site komt. Verder rekenen de kaders hun hoogte uit door de tekst af te breken zoals hij op papier afbreekt, dus de openingstekst loopt niet meer onder zijn kader uit, en de 404-controle op het omslagbeeld kijkt ook naar het begin van de zichtbare tekst." },
  { datum: "2026-08-11", tekst: "Klik je op een copy- of analyselink van een pagina zonder Drive-bestand, dan kreeg je ruwe tekst in plaats van het opgemaakte stuk. Er is nu een knop die het document in de huisstijl opbouwt uit wat er al ligt, met of zonder Drive-map; bij copy is dat de volledige klant-briefing met omslag, uitleg, zoekwoorden en webteksten." },
  { datum: "2026-08-11", tekst: "Elke pagina die opgeruimd wordt krijgt nu ook een voorgestelde bestemming, met twee knoppen ernaast: de redirect plaatsen en de redirect testen. De bestemming volgt een vaste ladder (de inhoudelijke opvolger, anders de dichtstbijzijnde zusterpagina, anders de categorie erboven, anders een 410, en alleen bij externe links de homepage), en bij een plaatspagina is dichtstbijzijnde letterlijk te nemen: de ligging wordt opgezocht bij de plaatsendienst van de overheid en de bestemming is de vestiging die het dichtst bij ligt, waarbij alleen plaatsen tellen waar de klant echt zit. Dat maakt uit: bij One Day Clinic haalt het locatie-overzicht nul bezoekers terwijl de vijf stadspagina's er samen ruim vijftienhonderd per maand halen, dus alles naar dat overzicht sturen voedde precies de zwakste pagina. Boven veertig kilometer is een andere stad geen vervanging meer en gaat de pagina alsnog naar het overzicht. Testen vertelt wat een bezoeker echt krijgt: welke status, hoeveel tussenstappen, waar je uitkomt, of dat eindpunt bestaat en indexeerbaar is, en of er een cache voor de site zit die de oude pagina nog toont." },
  { datum: "2026-08-11", tekst: "De mailknop bij een taak in de developerlijst deed niets meer, terwijl er niets aan die knop veranderd was: hij sprong naar je eigen mailprogramma, en dat werkt alleen zolang er in die browser een mailprogramma aan mailadressen hangt. Valt dat weg, dan gebeurt er letterlijk niets, geen venster en geen melding, dus lijkt de knop stuk. Nu opent hetzelfde mailvenster als overal elders in het dashboard, met de klant, de taak, de pagina en de documenten er al in, en verstuurt hij via de mailkoppeling; het adres erboven is aan te passen en wordt onthouden, want de een mailt zijn sitebouwer en de ander mailt juist terug. Dezelfde constructie stond op drie plekken los in de code, dus dezelfde storing lag drie keer klaar; die lopen nu over één stukje code, en een proef bij elke bouw houdt tegen dat er een nieuwe mailknop bijkomt die stilzwijgend niets kan doen." },
  { datum: "2026-08-11", tekst: "Een vraag in de chat van een projectkaart kon zonder antwoord én zonder melding blijven hangen: de reden werd wel bepaald, maar getekend in de fase-lijst, en een kaart zonder pagina heeft die lijst niet. Je zag dus niets, stelde de vraag opnieuw, en had twee identieke vragen zonder antwoord in beeld. Nu staat de melding onder de vraag zelf, komt je vraag terug in het invulveld zodat overtypen of plakken niet meer nodig is, en zit er een knop 'Probeer opnieuw' naast. Daarnaast kapt het dashboard een te zware vraag nu zelf af, net vóór de tijdslimiet van de server, met een leesbare uitleg in plaats van een leeg scherm, en beginnen de extra denkrondes (afronden, uitschrijven, feitencontrole) alleen nog als er ook echt tijd voor is, zodat een compleet antwoord niet meer verloren gaat aan een ronde die er niet meer bij paste." },
  { datum: "2026-08-11", tekst: "Het nieuws op deze pagina stond als één zin van vijfduizend tekens op één regel, en elke chat die iets opleverde herschreef precies die regel; twee chats op dezelfde dag botsten dus altijd, en vandaag zijn de conflictmarkeringen twee keer meegecommit, waardoor de bouw mislukte en de site twee opleveringen lang op oude code bleef staan zonder dat iemand het zag. Nu is één oplevering één regel die je erbij zet in plaats van een regel die je herschrijft, houdt git bij een botsing beide regels in plaats van er een conflict van te maken, en mislukt de bouw met een leesbare melding zodra er ergens toch een half samengevoegd bestand in de code staat. Zichtbaar gevolg: de kopbalk toont weer gewoon een datum, en het nieuws staat in een eigen uitklapper met een regel per oplevering." },
  { datum: "2026-08-11", tekst: "Elke pagina die opgeruimd wordt krijgt nu ook een voorgestelde bestemming, gekozen langs een vaste keuzeladder: de inhoudelijke opvolger, anders de dichtstbijzijnde zuster, anders de categorie erboven, anders 410, en alleen bij externe links de homepage. Bij het voorstel staat welke trede het werd, waarom de hogere treden afvielen, en hoe zwaar de keuze weegt (externe links en resterend verkeer). Ernaast twee knoppen: de redirect plaatsen (die meet zichzelf daarna na) en de redirect testen (status, aantal tussenstappen, eindpunt, en of dat eindpunt 200 geeft en indexeerbaar is). Bij plaatspagina's wordt de zusterstad bewust overgeslagen en 410 is een volwaardige uitkomst in plaats van een fout." },
  { datum: "2026-08-11", tekst: "Een documentlink opent nu meteen in Google Docs in bewerkmodus in plaats van in het kijkscherm van Drive, ook bij documenten die er al maanden staan; een pdf of afbeelding houdt zijn gewone Drive-link. En een kop staat nooit meer alleen onderaan een bladzijde met zijn tekst op de volgende: koppen, tabelkopregels en de witregel eronder schuiven mee. Dat zit in de bouwstenen, dus het geldt voor elk Pingwin-document, en een proef controleert het bij elke bouw in het echte Word-bestand." },
  { datum: "2026-08-11", tekst: "Uitgezocht waarom de paginatitel en de omschrijving niet altijd aan de criteria voldeden: we gaven het model een regel in tekens en rekenden het af in pixels, en die twee liepen niet gelijk. Een omschrijving van 129 tekens haalde onze eigen tekenregel en bleef 20 pixels onder het venster van Google. De pixel is nu de enige norm, het tekenbereik wordt daaruit afgeleid en aan de tekst zelf gemeten. Daarbovenop: het model hoort hoeveel het scheelt in plaats van alleen dat het mis is, het levert drie varianten per ronde in plaats van een, en er is een vijl die met puur rekenwerk inkort op een natuurlijke grens of aanvult met eigen woorden van de klant, en die niets doet als het resultaat niet echt klopt. Haalt een tekst het dan nog niet, dan meldt het dashboard dat bij de oplevering in plaats van te zwijgen." },
  { datum: "2026-08-11", tekst: "Klik je op een copy- of analyselink zonder Drive-bestand, dan krijg je nu het opgemaakte Word-document in de huisstijl in plaats van ruwe tekst." },
  { datum: "2026-08-11", tekst: "De copy-briefing voor de klant is opgeschoond: de uitleg stond er twee keer in (een keer vers opgebouwd, een keer uit het opgeslagen copy-document) en de paginatitel en omschrijving ook; nu wordt uit dat opgeslagen document alleen het deel overgenomen dat er nog niet staat, de webteksten. De niveau-aanduidingen H1/H2/H3 staan daardoor weer alleen bij tekst die echt op de site komt, niet boven de hoofdstukken van de briefing. Het blok met de paginatitel en de omschrijving heeft geen oordeelkolom meer: alleen de opgeleverde tekst plus de meting. De kaders in een document berekenen hun hoogte nu door de tekst echt af te breken zoals hij op het scherm afbreekt, dus de openingstekst loopt niet meer onder zijn kader uit. Een hoofdstuktitel krijgt lucht boven zich en blijft aan zijn eerste alinea vastgeplakt, dus hij blijft niet meer als losse regel onderaan een pagina achter. En de 404-controle op het omslagbeeld kijkt ook naar het begin van de zichtbare tekst, want niet elk thema zet \"404\" in een echte kop." },
  { datum: "2026-08-11", tekst: "De Drive-map van een pagina kies of maak je nu bovenaan de fases, waar de documenten ook gemaakt worden. Bestaat die map nog niet (bij een nieuwe pagina is dat de regel), dan maak je hem in hetzelfde venster, met een voorgestelde naam uit het pad van de pagina, en sta je er meteen in zodat hij ook echt vastgelegd wordt; eerder werd de map wel gemaakt maar niet gekozen, en landden de documenten een niveau hoger. Het vinkje “geldt” bij een document verschijnt alleen nog als er meer dan één versie van dat soort ligt; is er maar één, dan geldt die vanzelf, ook op de kaarten die er al stonden. De standaardzinnetjes per fase (“tekst aanscherpen”, “toets deze pagina op overlap”) zijn uit beeld: die herhaalden alleen de naam van de fase en bleven staan als de fase allang af was. En het archief onderaan de kaart heet nu “Oude versies van deze kaart” met de waarschuwing erbij dat het niet actueel is." },
  { datum: "2026-08-11", tekst: "Documentlinks openen overal in een nieuw tabblad in plaats van een los venster; documenten staan overal in proces-volgorde (analyse, blauwdruk, copy) in plaats van nieuwste eerst; en een gegenereerde tekst zonder Drive-bestand heeft nu altijd een link, naar de interne documentweergave." },
  { datum: "2026-08-11", tekst: "De cockpit opent een stuk sneller, doordat de app niet meer bij elke koude server honderd keer controleert of de database klopt, elk tabblad pas gedownload wordt als je het opent, en de planning haar gegevens meteen ophaalt in plaats van te wachten tot alle code binnen is." },
  { datum: "2026-08-11", tekst: "De controle “Is dit doorgevoerd?” zoekt het copydocument op alle plekken waar het kan liggen, inclusief het gekoppelde document in Drive." },
  { datum: "2026-08-11", tekst: "In de kaart-chat staan de knoppen “Mail deze analyse” en “Vat samen & leg strategie vast” direct onder het antwoord; de dossierkaartjes van pagina's die in het antwoord genoemd worden staan erónder en standaard ingeklapt. Het samenvatten leest bovendien het hele gesprek ruim terug, dus ook een lange analyse gaat volledig mee." },
  { datum: "2026-08-11", tekst: "Aantekeningen bij een taak bewaren zichzelf, ook als je de taak meteen dichtklapt of wegklikt; een opengeklapte taak wordt zichtbaar uit de lijst gelicht; een nieuwe taak is nog één regel typen, waarbij de pagina uit je eigen zin gelezen wordt." },
  { datum: "2026-08-11", tekst: "De strategie vastleggen kan ook rechtstreeks op de projectkaart in de planning; de verwarrende losse knop “Strategie vastleggen” is vervangen door een eerlijk benoemde herkansing “Document opnieuw maken”; de vrije tekstvelden houden een geschiedenis bij en zijn met één klik terug te zetten via Veld terugzetten; en “Hele site opnieuw scannen” meet nu ook echt de inhoud van elke pagina, waarbij de wekelijkse scan begint bij de klant die het langst niet aan de beurt is geweest." },
  { datum: "2026-08-11", tekst: "De koppencontrole vergeleek de hoofdstukken van ons eigen copydocument met de pagina en meldde daardoor \"0 van de 5 koppen gevonden\" terwijl de teksten er gewoon op stonden; hij vergelijkt nu de echte webteksten, kiest het document dat die teksten bevat, en laat in een uitklapper zien welke koppen hij zocht en welke hij vond." },
];

const MAAND = ["januari", "februari", "maart", "april", "mei", "juni", "juli", "augustus", "september", "oktober", "november", "december"];

/** "11 augustus 2026". Leeg als de datum niet klopt. */
export function leesbareDatum(iso: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec((iso || "").trim());
  if (!m) return "";
  return `${Number(m[3])} ${MAAND[Number(m[2]) - 1]} ${m[1]}`;
}

/** Nieuwste eerst. Een union-merge kan de volgorde door elkaar gooien; dit zet hem recht. */
export function nieuwtjes(): Nieuwtje[] {
  return [...WAT_IS_NIEUW].filter((n) => leesbareDatum(n.datum)).sort((a, b) => (a.datum < b.datum ? 1 : a.datum > b.datum ? -1 : 0));
}
